// ── UTILITY FUNCTIONS ─────────────────────────────────────────────────────
function safeImpliedOdds(prob) {
  if (!prob || prob <= 0 || prob > 100) return null;
  const raw = 1 / ((prob / 100) * 0.95);
  return isFinite(raw) && raw > 1 ? parseFloat(raw.toFixed(2)) : null;
}

function oddsOrImplied(realOdds, prob) {
  if (realOdds && isFinite(realOdds) && realOdds > 1.01) return parseFloat(realOdds);
  const implied = safeImpliedOdds(prob);
  // Floor at 1.02 — very high-confidence picks (95%+) still deserve a slot in the parlay.
  // Without floor, implied=1.01 fails the >1.0 check in generateTickets and pick is dropped.
  return implied || 1.02;
}

// ── N1-FIX: copyToClipboard — execCommand-only. Safe on Android WebView.
// Root cause of the still-firing permission prompt: navigator.clipboard.writeText()
// triggers the Android permission dialog the moment it is CALLED, before the
// promise rejects — even though we had a .catch fallback. The permission dialog
// fires at call-time, not at resolve/reject time.
// Fix: skip the Async Clipboard API entirely and use execCommand('copy') directly.
// execCommand is synchronous, requires no permission, and works in all Android
// WebViews. Modern desktop browsers also support it as a fallback. The only
// environment that truly needs the Async API is Safari 13.3+ on iOS — but iOS
// does not trigger a visible permission dialog for clipboard, so skipping it is safe.
// B-FIX (foundation): stamp `.date` onto every fixture at load time. Fixture
// objects didn't carry their own date before — needed both for the Fixture
// Share deep link (A) to know what date a shared fixture came from, and as
// the foundation for Multi-Date Live Model (B), where a single `fixtures`
// array will eventually hold fixtures from more than one date at once.
// Additive only: never overwrites a date a fixture already carries.
function stampFixtureDates(fixturesArr, d) {
  if (!Array.isArray(fixturesArr) || !d) return fixturesArr;
  return fixturesArr.map(f => (f && !f.date) ? { ...f, date: d } : f);
}

// Usage: copyToClipboard(text, onSuccess?, onError?)
export function copyToClipboard(text, onSuccess, onError) {
  _execCommandCopy(text, onSuccess, onError);
}

function _execCommandCopy(text, onSuccess, onError) {
  try {
    const el = document.createElement("textarea");
    el.value = text;
    // Off-screen but within viewport so iOS doesn't scroll
    el.style.cssText = "position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none;";
    document.body.appendChild(el);
    el.focus();
    el.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(el);
    if (ok) onSuccess?.();
    else onError?.();
  } catch {
    onError?.();
  }
}

// Infer market string from free-text pick label (used by TicketBookNowButton / buildLegs)
function inferMarket(pick = "") {
  const p = pick.toLowerCase();
  if (/\bwin\b/.test(p))                    return "1X2";
  if (/draw/.test(p))                       return "1X2";
  if (/home or|away or|or away/.test(p))    return "DC";
  if (/btts|both teams/.test(p))            return "BTTS";
  if (/over|under/.test(p)) {
    if (/corner/.test(p))                   return "Corners";
    if (/home|away/.test(p.split("over")[0] + p.split("under")[0])) return "TeamTotal";
    const line = (p.match(/[\d.]+/) || ["2.5"])[0];
    return p.includes("over") ? `Over ${line}` : `Under ${line}`;
  }
  if (/clean sheet|cs/.test(p))             return "CS";
  return "1X2";
}

function evalPickResult(pickLabel, market, hGoals, aGoals, homeName, awayName) {
  if (hGoals == null || aGoals == null) return null;
  const total = hGoals + aGoals, p = pickLabel || "", m = market || "";
  if (p === "Over 1.5 Goals"  || m === "Over 1.5")  return total > 1 ? "WIN" : "LOSS";
  if (p === "Over 2.5 Goals"  || m === "Over 2.5")  return total > 2 ? "WIN" : "LOSS";
  if (p === "Over 3.5 Goals"  || m === "Over 3.5")  return total > 3 ? "WIN" : "LOSS";
  if (p === "Over 4.5 Goals"  || m === "Over 4.5")  return total > 4 ? "WIN" : "LOSS";
  if (p === "Under 1.5 Goals" || m === "Under 1.5") return total < 2 ? "WIN" : "LOSS";
  if (p === "Under 2.5 Goals" || m === "Under 2.5") return total < 3 ? "WIN" : "LOSS";
  if (p === "Under 3.5 Goals" || m === "Under 3.5") return total < 4 ? "WIN" : "LOSS";
  if (p === "Under 4.5 Goals" || m === "Under 4.5") return total < 5 ? "WIN" : "LOSS";
  if (p === "BTTS Yes") return (hGoals > 0 && aGoals > 0) ? "WIN" : "LOSS";
  if (p === "BTTS No")  return (hGoals === 0 || aGoals === 0) ? "WIN" : "LOSS";
  if (p === "Draw")     return hGoals === aGoals ? "WIN" : "LOSS";
  if (m === "DC") {
    // E4-FIX: Fragile 6-char slug match (awayName.slice(0,6)) caused collisions on teams
    // sharing a name prefix (e.g. "Manchester City" vs "Manchester United" → both "manche").
    // Also, pLow.includes("or draw") broke when pick was formatted as "Draw or Away".
    // Fix: match against canonical DC pick labels in all supported formats.
    const pLow = p.toLowerCase().trim();
    // 1X / Home or Draw / Home Win or Draw
    const is1X = pLow === "1x" || pLow === "home or draw" || pLow === "draw or home" || pLow.startsWith("home win or draw") || pLow.startsWith("home or draw");
    // X2 / Away or Draw / Draw or Away
    const isX2 = pLow === "x2" || pLow === "draw or away" || pLow === "away or draw" || pLow.startsWith("away win or draw") || pLow.startsWith("draw or away");
    // 12 / Home or Away (no draw)
    const is12 = pLow === "12" || pLow === "home or away" || pLow === "away or home";
    if (is1X) return hGoals >= aGoals ? "WIN" : "LOSS";  // home win OR draw
    if (isX2) return aGoals >= hGoals ? "WIN" : "LOSS";  // away win OR draw
    if (is12) return hGoals !== aGoals ? "WIN" : "LOSS"; // either team wins (no draw)
    // Unrecognised DC pick format — fall through to null
    return null;
  }
  if (homeName && p === `${homeName} Win`) return hGoals > aGoals ? "WIN" : "LOSS";
  if (awayName && p === `${awayName} Win`) return aGoals > hGoals ? "WIN" : "LOSS";
  if (p.endsWith(" Win")) {
    if (homeName && p.startsWith(homeName.slice(0, 6))) return hGoals > aGoals ? "WIN" : "LOSS";
    if (awayName && p.startsWith(awayName.slice(0, 6))) return aGoals > hGoals ? "WIN" : "LOSS";
  }
  if (p.includes("to Score") || p.includes("O0.5")) {
    const isHome = homeName && p.startsWith(homeName.slice(0, 6));
    return (isHome ? hGoals : aGoals) > 0 ? "WIN" : "LOSS";
  }
  if (p.includes("O1.5") || p.includes("Over 1.5")) {
    const isHome = homeName && p.startsWith(homeName.slice(0, 6));
    return (isHome ? hGoals : aGoals) > 1 ? "WIN" : "LOSS";
  }
  return null;
}

function abbreviatePick(pick, home, away) {
  if (!pick) return null;

  // Standard market names — shorten inline
  const SHORT_MAP = {
    "Over 1.5 Goals": "O1.5", "Over 2.5 Goals": "O2.5",
    "Over 3.5 Goals": "O3.5", "Over 4.5 Goals": "O4.5",
    "Under 1.5 Goals": "U1.5", "Under 2.5 Goals": "U2.5",
    "Under 3.5 Goals": "U3.5", "Under 4.5 Goals": "U4.5",
    "Over 1.5": "O1.5", "Over 2.5": "O2.5",
    "Over 3.5": "O3.5", "Over 4.5": "O4.5",
    "Under 1.5": "U1.5", "Under 2.5": "U2.5",
    "Under 3.5": "U3.5", "Under 4.5": "U4.5",
    "BTTS Yes": "BTTS ✓", "BTTS No": "BTTS ✗",
    "Draw": "Draw",
  };
  if (SHORT_MAP[pick]) return SHORT_MAP[pick];

  // Win picks
  if (home && pick === `${home} Win`) {
    const candidate = home.length <= 8 ? `${home} Win` : "Home Win";
    return candidate;
  }
  if (away && pick === `${away} Win`) {
    const candidate = away.length <= 8 ? `${away} Win` : "Away Win";
    return candidate;
  }
  // Fallback for partial name match (slice-based from evalPickResult)
  if (pick.endsWith(" Win")) {
    const teamPart = pick.slice(0, -4);
    if (home && home.startsWith(teamPart)) return home.length <= 8 ? `${home} Win` : "Home Win";
    if (away && away.startsWith(teamPart)) return away.length <= 8 ? `${away} Win` : "Away Win";
    return teamPart.length <= 8 ? pick : "Home Win";
  }

  // "to Score" / O0.5 team total
  const toScorePattern = /^(.+?)\s+(?:to Score|O0\.5)$/i;
  const toScoreMatch = pick.match(toScorePattern);
  if (toScoreMatch) {
    const teamName = toScoreMatch[1];
    const isHome = home && (pick.startsWith(home) || teamName === home);
    const role = isHome ? "H" : "A";
    const candidate = teamName.length <= 6 ? `${teamName} O0.5` : `${role} O0.5`;
    return candidate.length <= 12 ? candidate : `${role} O0.5`;
  }

  // O1.5 team total
  const o15Pattern = /^(.+?)\s+O1\.5$/i;
  const o15Match = pick.match(o15Pattern);
  if (o15Match) {
    const teamName = o15Match[1];
    const isHome = home && (pick.startsWith(home) || teamName === home);
    const role = isHome ? "H" : "A";
    const candidate = teamName.length <= 6 ? `${teamName} O1.5` : `${role} O1.5`;
    return candidate.length <= 12 ? candidate : `${role} O1.5`;
  }

  // Goal Radar picks formatted as "TeamName O0.5" or "TeamName O1.5"
  if (home && pick.startsWith(home)) {
    const suffix = pick.slice(home.length).trim();
    const short = suffix.replace("to Score", "O0.5").replace("Over 0.5", "O0.5").replace("Over 1.5", "O1.5");
    const candidate = `H ${short}`;
    return candidate.length <= 12 ? candidate : `H ${short.slice(0, 8)}`;
  }
  if (away && pick.startsWith(away)) {
    const suffix = pick.slice(away.length).trim();
    const short = suffix.replace("to Score", "O0.5").replace("Over 0.5", "O0.5").replace("Over 1.5", "O1.5");
    const candidate = `A ${short}`;
    return candidate.length <= 12 ? candidate : `A ${short.slice(0, 8)}`;
  }

  // DC picks — usually short enough, just hard-cap
  if (pick.length <= 12) return pick;
  return pick.slice(0, 11) + "…";
}

// ── CUSTOM PICK HELPERS ───────────────────────────────────────────────────
function getCustomPick(f, family, C) {
  const m = f.markets, io = safeImpliedOdds;
  if (family === "theRead") {
    if (!f.theRead?.anchor) return null;
    const a = f.theRead.anchor, mst = mktStyle(a.market, f._sport);
    return { label:a.pick, prob:a.prob, odds:a.odds||io(a.prob), color:mst.color, market:a.market };
  }
  if (family === "theEdge") {
    if (!f.theEdge) return null;
    return { label:f.theEdge.pick, prob:f.theEdge.prob, odds:f.theEdge.odds||io(f.theEdge.prob), color:C?.edge, market:f.theEdge.market };
  }
  if (family === "goalRadar") {
    // football only — f.goalRadar is always null for basketball (set in
    // toFixtureShape), so this naturally returns null for BB without a guard
    const best = f.goalRadar?.home?.prob >= f.goalRadar?.away?.prob ? f.goalRadar?.home : f.goalRadar?.away;
    if (!best) return null;
    return { label:best.pick, prob:best.prob, odds:best.odds||io(best.prob), color:C?.radar, market:"TeamTotal" };
  }

  // ── BASKETBALL / TENNIS — market-odds-only families ───────────────────
  // These resolve directly from f.odds._raw since neither engine currently
  // produces confidence-scored predictions for these markets (see ENGINE GAP
  // notes in sportConfig.js). Each helper below pulls the first matching
  // market+choice pair and converts fractional odds to decimal + implied prob.
  if (f._sport === "basketball" || f._sport === "tennis") {
    const fracToDecimal = (frac) => {
      if (typeof frac === "number") return frac;
      if (typeof frac === "string" && frac.includes("/")) {
        const [n, d] = frac.split("/").map(Number);
        if (!isNaN(n) && !isNaN(d) && d > 0) return parseFloat((n/d + 1).toFixed(2));
      }
      return null;
    };
    const impliedFromDecimal = (dec) => dec > 1 ? Math.round((1/dec) * 100) : null;
    const raw = f.odds?._raw || {};

    // Home/Away handicap — find the "Handicap" market, pick the favourite/dog line
    if (family === "homehandicap" || family === "awayhandicap") {
      const hcMarket = raw["Handicap"] || raw["Handicap (incl. overtime)"] || null;
      if (!hcMarket) return null;
      const isHome = family === "homehandicap";
      // Lines are keyed like "-7.5" / "+7.5" — pick first negative for home, positive for away
      const lineKey = Object.keys(hcMarket).find(k =>
        isHome ? k.trim().startsWith("-") : k.trim().startsWith("+")
      );
      if (!lineKey) return null;
      const dec = fracToDecimal(hcMarket[lineKey]);
      if (dec == null) return null;
      const teamName = isHome ? f.teams.home : f.teams.away;
      return { label:`${teamName} ${lineKey}`, prob:impliedFromDecimal(dec), odds:dec, color:C?.blue, market:"Handicap" };
    }

    // Team Total (radar equivalent) — find "<TeamName> Over/Under" market
    if (family === "teamtotal_home" || family === "teamtotal_away") {
      const isHome   = family === "teamtotal_home";
      const teamName = isHome ? f.teams.home : f.teams.away;
      const marketKey = Object.keys(raw).find(k => k.toLowerCase().includes(teamName.toLowerCase()));
      if (!marketKey) return null;
      const lines = raw[marketKey];
      const firstLine = Object.keys(lines || {})[0];
      if (!firstLine) return null;
      const overFrac = lines[firstLine]?.["Over"] ?? lines[firstLine]?.Over;
      const dec = fracToDecimal(overFrac);
      if (dec == null) return null;
      return { label:`${teamName} O${firstLine}`, prob:impliedFromDecimal(dec), odds:dec, color:C?.radar, market:"Team Total" };
    }

    // Quarter winner — find "<N>(st|nd|rd|th) quarter - 1x2" market
    const Q_ORD = { q1_winner:"1st", q2_winner:"2nd", q3_winner:"3rd", q4_winner:"4th" };
    if (Q_ORD[family]) {
      const ord = Q_ORD[family];
      const marketKey = Object.keys(raw).find(k => k.toLowerCase().includes(`${ord.toLowerCase()} quarter`) && k.toLowerCase().includes("1x2"));
      if (!marketKey) return null;
      const choices = raw[marketKey];
      const dec = fracToDecimal(choices?.["Home"] ?? choices?.["1"]);
      if (dec == null) return null;
      return { label:`${f.teams.home} ${ord} Qtr`, prob:impliedFromDecimal(dec), odds:dec, color:C?.gold, market:"Quarter Winner" };
    }

    // Q1 margin — "1st quarter - winning margin"
    if (family === "q1_margin") {
      const marketKey = Object.keys(raw).find(k => k.toLowerCase().includes("1st quarter") && k.toLowerCase().includes("margin"));
      if (!marketKey) return null;
      const choices = raw[marketKey];
      const dec = fracToDecimal(choices?.["Home by 3+"]);
      if (dec == null) return null;
      return { label:`${f.teams.home} by 3+ (Q1)`, prob:impliedFromDecimal(dec), odds:dec, color:C?.dc, market:"Quarter Margin" };
    }

    // 1st Half Handicap
    if (family === "fh_handicap") {
      const marketKey = Object.keys(raw).find(k => k.toLowerCase().includes("1st half") && k.toLowerCase().includes("handicap"));
      if (!marketKey) return null;
      const choices = raw[marketKey];
      const lineKey = Object.keys(choices || {}).find(k => k.trim().startsWith("-"));
      if (!lineKey) return null;
      const dec = fracToDecimal(choices[lineKey]);
      if (dec == null) return null;
      return { label:`${f.teams.home} ${lineKey} (1H)`, prob:impliedFromDecimal(dec), odds:dec, color:C?.blue, market:"1st Half Handicap" };
    }

    // Tennis set handicap
    if (family === "sethandicap_h" || family === "sethandicap_a") {
      const marketKey = Object.keys(raw).find(k => k.toLowerCase().includes("set handicap"));
      if (!marketKey) return null;
      const choices = raw[marketKey];
      const isHome = family === "sethandicap_h";
      const lineKey = Object.keys(choices || {}).find(k => isHome ? k.trim().startsWith("-") : k.trim().startsWith("+"));
      if (!lineKey) return null;
      const dec = fracToDecimal(choices[lineKey]);
      if (dec == null) return null;
      const teamName = isHome ? f.teams.home : f.teams.away;
      return { label:`${teamName} ${lineKey} sets`, prob:impliedFromDecimal(dec), odds:dec, color:C?.blue, market:"Set Handicap" };
    }

    // homewin / awaywin / over_total / under_total for BB/tennis use the
    // SAME family IDs as football but need different resolution since BB/tennis
    // markets/probability fields differ:
    if (family === "homewin") {
      if (m.homeWin == null) return null;
      return { label:`${f.teams.home} Win`, prob:m.homeWin, odds:f.odds?.o1||io(m.homeWin), color:C?.gold, market:"Moneyline" };
    }
    if (family === "awaywin") {
      if (m.awayWin == null) return null;
      return { label:`${f.teams.away} Win`, prob:m.awayWin, odds:f.odds?.o2||io(m.awayWin), color:C?.gold, market:"Moneyline" };
    }
    if (family === "over_total" && f._totalSignal) {
      return { label:`Over ${f._totalSignal.line}`, prob:f._totalSignal.direction === "OVER" ? f._totalSignal.confidence : 100 - f._totalSignal.confidence, odds:null, color:C?.green, market:"Total" };
    }
    if (family === "under_total" && f._totalSignal) {
      return { label:`Under ${f._totalSignal.line}`, prob:f._totalSignal.direction === "UNDER" ? f._totalSignal.confidence : 100 - f._totalSignal.confidence, odds:null, color:C?.blue, market:"Total" };
    }
    return null; // unrecognised family for this sport — fail safe, no crash
  }

  // ── FOOTBALL — existing logic, completely UNCHANGED below this line ────
  if (family === "dc1x") {
    const prob = m.dc1X ?? (m.homeWin != null && m.draw != null ? Math.min(99, m.homeWin + m.draw) : null);
    if (prob == null) return null;
    return { label:"Home or Draw", prob, odds:f.odds?.dc1X || io(prob), color:C?.gold, market:"DC" };
  }
  if (family === "dc2x") {
    const prob = m.dcX2 ?? (m.draw != null && m.awayWin != null ? Math.min(99, m.draw + m.awayWin) : null);
    if (prob == null) return null;
    return { label:"Away or Draw", prob, odds:f.odds?.dcX2 || io(prob), color:C?.gold, market:"DC" };
  }
  // Legacy safeBet/valuePick compat for old snapshots
  if (family === "safeBet") {
    if (!f.safeBet) return null;
    const mst = mktStyle(f.safeBet.market);
    return { label:f.safeBet.pick, prob:f.safeBet.prob, odds:f.safeBet.odds||io(f.safeBet.prob), color:mst.color, market:f.safeBet.market };
  }
  const map = {
    "over15":  { label:"Over 1.5",  prob:m.over15,   odds:io(m.over15),   color:C?.green  },
    "over25":  { label:"Over 2.5",  prob:m.over25,   odds:io(m.over25),   color:C?.green  },
    "over35":  { label:"Over 3.5",  prob:m.over35,   odds:io(m.over35),   color:C?.green  },
    "over45":  { label:"Over 4.5",  prob:m.over45,   odds:io(m.over45),   color:C?.green  },
    "under15": { label:"Under 1.5", prob:parseFloat((100-(m.over15||0)).toFixed(1)), odds:io(100-(m.over15||0)), color:C?.blue },
    "under25": { label:"Under 2.5", prob:m.under25,  odds:io(m.under25),  color:C?.blue   },
    "under35": { label:"Under 3.5", prob:m.under35,  odds:io(m.under35),  color:C?.blue   },
    "under45": { label:"Under 4.5", prob:m.under45,  odds:io(m.under45),  color:C?.blue   },
    "bttsyes": { label:"BTTS Yes",  prob:m.bttsYes,  odds:f.odds?.bttsYesOdds||io(m.bttsYes), color:C?.purple },
    "bttsno":  { label:"BTTS No",   prob:m.bttsNo,   odds:f.odds?.bttsNoOdds||io(m.bttsNo),   color:C?.purple },
    "homewin": { label:`${f.teams.home} Win`, prob:m.homeWin, odds:f.odds?.o1||io(m.homeWin), color:C?.gold, market:"1X2" },
    "draw":    { label:"Draw",      prob:m.draw,     odds:f.odds?.oX||io(m.draw), color:C?.gold, market:"1X2" },
    "awaywin": { label:`${f.teams.away} Win`, prob:m.awayWin, odds:f.odds?.o2||io(m.awayWin), color:C?.gold, market:"1X2" },
    "homeo05": { label:`${f.teams.home} O0.5`, prob:m.homeOver05, odds:io(m.homeOver05), color:C?.radar, market:"TeamTotal" },
    "homeo15": { label:`${f.teams.home} O1.5`, prob:m.homeOver15, odds:io(m.homeOver15), color:C?.radar, market:"TeamTotal" },
    "awayo05": { label:`${f.teams.away} O0.5`, prob:m.awayOver05, odds:io(m.awayOver05), color:C?.radar, market:"TeamTotal" },
    "awayo15": { label:`${f.teams.away} O1.5`, prob:m.awayOver15, odds:io(m.awayOver15), color:C?.radar, market:"TeamTotal" },
  };
  return map[family] || null;
}

const CUSTOM_FAMILIES = [
  { id:"theRead",   label:"The Read"   },
  { id:"theEdge",   label:"The Edge" },
  { id:"goalRadar", label:"Goal Radar" },
  { id:"over15",label:"O1.5" }, { id:"over25",label:"O2.5" }, { id:"over35",label:"O3.5" }, { id:"over45",label:"O4.5" },
  { id:"under15",label:"U1.5" }, { id:"under25",label:"U2.5" }, { id:"under35",label:"U3.5" }, { id:"under45",label:"U4.5" },
  { id:"bttsyes",label:"BTTS Yes" }, { id:"bttsno",label:"BTTS No" },
  { id:"homewin",label:"Home Win" }, { id:"draw",label:"Draw" }, { id:"awaywin",label:"Away Win" },
  { id:"dc1x",label:"DC 1X" }, { id:"dc2x",label:"DC X2" },
  { id:"homeo05",label:"H O0.5" }, { id:"homeo15",label:"H O1.5" }, { id:"awayo05",label:"A O0.5" }, { id:"awayo15",label:"A O1.5" },
];

// ══════════════════════════════════════════════════════════════════════════
// SA PATTERN ENGINE — client-side port of strategy-analyst.mjs's feature
// extraction, so validated patterns from sa-patterns.json can be matched
// against live fixtures. Every formula below is a 1:1 mirror of the offline
// miner (same buckets, same thresholds) so a fixture that would have matched
// a pattern during training matches it here too. Admin-only feature.
// ══════════════════════════════════════════════════════════════════════════

// Market name → how to read its probability/odds off a live fixture.
const SA_MARKETS = {
  "TB:Over 1.5":      { probKey:"over15",  oddsKey:"over15odds"  },
  "TB:Over 2.5":      { probKey:"over25",  oddsKey:"over25odds"  },
  "TB:Under 3.5":     { probKey:"under35", oddsKey:"under35odds" },
  "TB:Under 4.5":     { probKey:"under45", oddsKey:"under45odds" },
  "TB:BTTS":          { probKey:"bttsYes", oddsKey:"bttsYesOdds" },
  "TB:DC1X":          { computeProb: m => (+(m.homeWin??0)) + (+(m.draw??0)), oddsKey:"dc1X" },
  "TB:DCX2":          { computeProb: m => (+(m.draw??0)) + (+(m.awayWin??0)), oddsKey:"dcX2" },
  "TB:1X2-Home":      { probKey:"homeWin", oddsKey:"o1" },
  "TB:1X2-Draw":      { probKey:"draw",    oddsKey:"oX" },
  "TB:1X2-Away":      { probKey:"awayWin", oddsKey:"o2" },
  "TB:Home Over 0.5": { probKey:"homeOver05", oddsKey:null },
  "TB:Home Over 1.5": { probKey:"homeOver15", oddsKey:null },
  "TB:Away Over 0.5": { probKey:"awayOver05", oddsKey:null },
  "TB:Away Over 1.5": { probKey:"awayOver15", oddsKey:null },
  // PE Mix — virtual view: each fixture shows whichever gated market PE assigned
  // as its home market (strongest SA signal for that game today). Not a real market
  // key — handled as a special case in the saRows memo below.
  "PE:Mix":           { _isPEMix: true },
};
const SA_MARKET_LABELS = [...Object.keys(SA_MARKETS)].map(id => ({
  id,
  label: id === "PE:Mix" ? "Mix" : id.replace(/^TB:/, ""),
}));

// Selecting an SA Pattern market should make the normal Pick Market filter
// follow it, so both selectors stay in sync instead of showing two different
// markets at once. CUSTOM_FAMILIES uses different (lowercase, unprefixed)
// ids than SA_MARKETS — this is the explicit mapping between the two schemes.
const SA_TO_FAMILY_ID = {
  "TB:Over 1.5": "over15", "TB:Over 2.5": "over25",
  "TB:Under 3.5": "under35", "TB:Under 4.5": "under45",
  "TB:BTTS": "bttsyes",
  "TB:DC1X": "dc1x", "TB:DCX2": "dc2x",
  "TB:1X2-Home": "homewin", "TB:1X2-Draw": "draw", "TB:1X2-Away": "awaywin",
  "TB:Home Over 0.5": "homeo05", "TB:Home Over 1.5": "homeo15",
  "TB:Away Over 0.5": "awayo05", "TB:Away Over 1.5": "awayo15",
};
// ── CA_FAMILY_ALTERNATES (2026-07-19, Alden's report) ───────────────────────
// The "Pick Market" row (family/setFamily) auto-syncs to a CA market's own
// default family the moment you click that CA market button — but caRows
// then recomputed `family` fresh from the CA market on every render after
// that, never looking at the Pick Market row again. Switching Pick Market
// from "BTTS Yes" to "BTTS No" while browsing CA:BTTS visibly did nothing —
// same for every other market, not BTTS-specific.
// Fix: caRows now respects a manual Pick Market choice, but ONLY when it's
// an actual probability-complement of the CA market being shown (same
// underlying line, opposite side) — not an arbitrary unrelated market. Each
// CA market maps to the family ids that are valid for it; the CA market's
// own default is always included first so "haven't touched Pick Market"
// behaves exactly as before.
const CA_FAMILY_ALTERNATES = {
  "TB:Over 1.5":     ["over15", "under15"],
  "TB:Over 2.5":     ["over25", "under25"],
  "TB:Under 3.5":    ["under35", "over35"],
  "TB:Under 4.5":    ["under45", "over45"],
  "TB:BTTS":         ["bttsyes", "bttsno"],
  "TB:DC1X":         ["dc1x", "awaywin"],   // DC1X (Home-or-Draw) complements Away Win exactly
  "TB:DCX2":         ["dc2x", "homewin"],   // DCX2 (Away-or-Draw) complements Home Win exactly
  "TB:1X2-Home":     ["homewin", "dc2x"],
  "TB:1X2-Draw":     ["draw"],
  "TB:1X2-Away":     ["awaywin", "dc1x"],
  "TB:Home Over 0.5": ["homeo05"],
  "TB:Home Over 1.5": ["homeo15"],
  "TB:Away Over 0.5": ["awayo05"],
  "TB:Away Over 1.5": ["awayo15"],
};
// Given the CA market just matched and whatever the Pick Market row is
// currently set to, return the family id caRows should actually display —
// the manual choice if it's a valid complement for this CA market, else the
// CA market's own default (index 0 of its alternates list).
function caResolveFamily(caMarketId, pickMarketFamily) {
  const alts = CA_FAMILY_ALTERNATES[caMarketId];
  if (!alts) return SA_TO_FAMILY_ID[caMarketId];
  return alts.includes(pickMarketFamily) ? pickMarketFamily : alts[0];
}

// CA row market list — same 13 TB: market strings as SA (CA and SA mine the
// identical 14-market scope, minus PE:Mix which is SA-specific), plus its
// own "CA:Mix" virtual entry. Reuses SA_TO_FAMILY_ID's keys directly rather
// than a second hardcoded list of the same 13 strings.
const CA_MARKET_LABELS = [...Object.keys(SA_TO_FAMILY_ID), "CA:Mix", "CA:Verdict"].map(id => ({
  id, label: id === "CA:Mix" ? "Mix" : id === "CA:Verdict" ? "Verdict" : id.replace(/^TB:/, ""),
}));

function saTheReadToTBMarket(anchor) {
  if (!anchor) return null;
  const mkt = anchor.market, dcV = anchor.dcVariant;
  if (mkt === "DC") return dcV === "1X" ? "TB:DC1X" : dcV === "X2" ? "TB:DCX2" : null;
  const MAP = {
    "Over 1.5":"TB:Over 1.5","Over 2.5":"TB:Over 2.5","Under 3.5":"TB:Under 3.5","Under 4.5":"TB:Under 4.5",
    "BTTS":"TB:BTTS","Home Over 0.5":"TB:Home Over 0.5","Away Over 0.5":"TB:Away Over 0.5",
    "Home Win":"TB:1X2-Home","Away Win":"TB:1X2-Away","Draw":"TB:1X2-Draw",
  };
  return MAP[mkt] ?? null;
}

const saProbBand = p => p>=90?"90+":p>=85?"85-90":p>=80?"80-85":p>=75?"75-80":p>=70?"70-75":p>=65?"65-70":"<65";
const saCalBand = w => w==null?"unknown":w>=80?"80+":w>=60?"60-80":w>=40?"40-60":w>=20?"20-40":"<20";
const saSeasonBand = n => !n?"unknown":n>=30?"30+":n>=20?"20-30":n>=8?"8-20":"<8";
const saGamesUsedBand = n => !n?"unknown":n>=60?"60+":n>=30?"30-60":n>=15?"15-30":"<15";
const saLeagueTier = rank => !rank?"unknown":rank<=10?"elite":rank<=20?"top":rank<=50?"mid":"lower";
const saXgRatioBand = (h,a) => { if(!h||!a||h<=0||a<=0) return "unknown"; const r=Math.max(h/a,a/h); return r>=3?"3+":r>=2?"2-3":r>=1.5?"1.5-2":"<1.5"; };
const saTotalXGBand = t => !t||t<=0?"unknown":t>=4?"4+":t>=3?"3-4":t>=2?"2-3":"<2";
const saOddsDiscrepBand = (modelProb, bkOdds) => {
  if (!bkOdds || bkOdds<=1) return "no-bk";
  const bkP = (1/bkOdds)*100, d = modelProb - bkP;
  return d>15?"strong-edge":d>5?"mild-edge":d>-5?"aligned":d>-15?"mild-against":"strong-against";
};
const saTablePosBand = pos => pos==null?"unknown":pos<=3?"top3":pos<=6?"top6":pos<=10?"mid":"bottom";
const saPosDiffBand  = d => d==null?"unknown":d<=3?"close":d<=7?"mid":"large";
const saBacktestWtBand = w => w==null?"unknown":w>=50?"50+":w>=30?"30-50":w>=15?"15-30":"<15";

// Computes the same feature dimensions strategy-analyst.mjs mined patterns
// against, off a LIVE fixture instead of a snapshot file. Returned object is
// keyed identically to sa-patterns.json's `conditions`, values stringified
// the same way (DIMS in the miner wraps booleans/bands in String()).
function computeSAFeatures(f, market) {
  const def = SA_MARKETS[market];
  if (!def) return null;
  const m = f.markets || {};
  const prob   = def.computeProb ? def.computeProb(m) : +(m[def.probKey] ?? 0);
  const bkOdds = def.oddsKey ? +(f.odds?.[def.oddsKey] ?? 0) : 0;

  const hXG = +(m.homeXG ?? 0), aXG = +(m.awayXG ?? 0);
  const tot = hXG + aXG, gap = Math.abs(hXG - aXG);

  const calW   = m._calibrationWeight ?? null;
  const sGames = m._seasonGames ?? null;
  const gUsed  = m._gamesUsed ?? null;
  const btW    = m._backtestWeight ?? null;
  const isLowConf = !!(m._lowConfidence ?? false);

  const lRank = f.leagueRank ?? null;
  const isVol = !!(f.volatileLeague ?? false);

  const hAtk = +(m.homeAttackStrength ?? 0), aAtk = +(m.awayAttackStrength ?? 0);
  const hDef = +(m.homeDefenceStrength ?? 0), aDef = +(m.awayDefenceStrength ?? 0);

  const tp = f.tablePosition || {};
  const hPos = tp.homePosition ?? null, aPos = tp.awayPosition ?? null;
  const posDiff = (hPos!=null && aPos!=null) ? Math.abs(hPos-aPos) : null;

  const hSt = f.teamStats?.home || {}, aSt = f.teamStats?.away || {};

  const readAnchor     = f.theRead?.anchor;
  const readStrong     = !!(readAnchor?.strong ?? false);
  const readTBMkt      = saTheReadToTBMarket(readAnchor);
  const readMatchesMkt = readTBMkt === market;

  const o25 = +(m.over25 ?? 0), btts = +(m.bttsYes ?? m.btts ?? 0), draw = +(m.draw ?? 0);
  const tags = f.strategyTags || [];

  return {
    probBand: saProbBand(prob),
    leagueTier: saLeagueTier(lRank),
    isEliteLeague: String(lRank!=null && lRank<999 && lRank<=10),
    isTopLeague:   String(lRank!=null && lRank<999 && lRank<=20),
    isVolatile: String(isVol),
    country: f.country || "unknown",
    calBand: saCalBand(calW),
    isHighCalib: String(calW!=null && calW>=70),
    gamesUsedBand: saGamesUsedBand(gUsed),
    isLowConf: String(isLowConf),
    backtestWtBand: saBacktestWtBand(btW),
    seasonBand: saSeasonBand(sGames),
    isLateSeason: String(sGames!=null && sGames>30),
    isEarlySeason: String(sGames!=null && sGames<8),
    xgRatioBand: saXgRatioBand(hXG, aXG),
    totalXGBand: saTotalXGBand(tot),
    xgBalanced: String(gap < 0.5),
    xgDomHome: String(hXG>0 && aXG>0 && hXG>=aXG*2 && gap>=1),
    xgDomAway: String(hXG>0 && aXG>0 && aXG>=hXG*2 && gap>=1),
    highTotalXG: String(tot >= 3),
    lowTotalXG: String(tot > 0 && tot < 1.5),
    xgSourceType: f.xgSource || "unknown",
    homeAttackStrong: String(hAtk >= 1.3),
    awayAttackStrong: String(aAtk >= 1.3),
    homeDefenceWeak: String(hDef >= 1.2),
    awayDefenceWeak: String(aDef >= 1.2),
    homeTablePos: saTablePosBand(hPos),
    awayTablePos: saTablePosBand(aPos),
    tablePosDiff: saPosDiffBand(posDiff),
    homeCsHigh: String((hSt.csRate ?? -1) >= 40),
    awayCsHigh: String((aSt.csRate ?? -1) >= 40),
    homeScoreLow: String((hSt.scoredRate ?? 101) <= 40),
    awayScoreLow: String((aSt.scoredRate ?? 101) <= 40),
    homeFtsHigh: String((hSt.ftsRate ?? -1) >= 40),
    awayFtsHigh: String((aSt.ftsRate ?? -1) >= 40),
    goalRange: f.goalRange || "unknown",
    highO25: String(o25 > 40),
    lowBtts: String(btts > 0 && btts < 35),
    highBtts: String(btts > 55),
    highDraw: String(draw > 30),
    hasBkOdds: String(!!(bkOdds && bkOdds>1)),
    oddsDiscrep: saOddsDiscrepBand(prob, bkOdds),
    readStrong: String(readStrong),
    readMatchesMkt: String(readMatchesMkt),
    hasLowScoring: String(tags.includes("low_scoring")),
    hasOver25Quality: String(tags.includes("over25_quality")),
    hasHomeWin: String(tags.includes("home_win")),
    hasAwayWin: String(tags.includes("away_win")),
    hasBttsValue: String(tags.includes("btts_value")),
    hasDrawTag: String(tags.includes("draw")),
    hasHomeGoalfest: String(tags.includes("home_goalfest")),
    hasAwayGoalfest: String(tags.includes("away_goalfest")),
  };
}

// Matches a fixture's computed features against every pattern for `market`.
// Returns { positive: [...matched, lift desc], avoid: [...matched, worst-first] }.
// Both single-condition and pair-condition patterns are handled the same way
// — every key in `p.conditions` must match the fixture's computed feature.
function matchSAPatterns(f, market, patterns) {
  const feats = computeSAFeatures(f, market);
  if (!feats || !patterns?.length) return { positive: [], avoid: [] };
  const positive = [], avoid = [];
  for (const p of patterns) {
    if (p.market !== market) continue;
    const matches = Object.entries(p.conditions).every(([k, v]) => feats[k] === v);
    if (!matches) continue;
    (p.direction === "positive" ? positive : avoid).push(p);
  }
  positive.sort((a,b) => b.lift - a.lift);
  avoid.sort((a,b) => a.lift - b.lift); // most negative lift first — worst offenders surfaced first within the flagged group
  return { positive, avoid };
}

// ── CA CONDITION MATCHER ──────────────────────────────────────────────────
// CA (conditions-analyst.mjs) conditions are continuous thresholds
// ({field, op, value}), not SA's tertile-bucket equality above — this is a
// direct port of conditions-analyst.mjs's extractDims() + conditionMatches(),
// run client-side against one fixture's live markets object. NOT a reuse of
// matchSAPatterns: the two systems check fundamentally different shapes of
// condition, so porting the real dims-extraction logic (not guessing at
// field names) matters — mismatched field names here would silently match
// nothing and look like "this fixture just has no CA matches" instead of
// erroring, which is worse than a crash.
// Field source is byte-for-byte the same as conditions-analyst.mjs's
// extractDims(): homeCS/awayCS/homeWin/awayWin/draw straight off f.markets,
// btts aliases m.bttsYes (falls back to m.btts), oddsFloor comes off
// f.theRead/f.theEdge (not m at all — it's a fixture-level field, not a
// markets one), totalXG is derived (homeXG + awayXG), not a stored field.
function caExtractDims(f) {
  const m = f.markets || {};
  const hXG = +(m.homeXG ?? 0), aXG = +(m.awayXG ?? 0);
  const oddsFloorRaw = f.theRead?.anchor?.odds ?? f.theEdge?.odds ?? null;
  return {
    totalXG: hXG + aXG, homeXG: hXG, awayXG: aXG,
    homeCS: +(m.homeCS ?? NaN), awayCS: +(m.awayCS ?? NaN),
    btts: +(m.bttsYes ?? m.btts ?? NaN),
    homeWin: +(m.homeWin ?? NaN), awayWin: +(m.awayWin ?? NaN), draw: +(m.draw ?? NaN),
    oddsFloor: oddsFloorRaw != null ? +oddsFloorRaw : NaN,
  };
}
function caConditionMatches(dims, cond) {
  const v = dims[cond.field];
  if (v == null || Number.isNaN(v)) return false;
  return cond.op === ">=" ? v >= cond.value : v < cond.value;
}
// caPatterns: the { byMarket, byMarketAvoid } payload from GET /api/ca-patterns.
// Returns { positive: [...matched combos, best holdout HR first], avoid: [...] },
// flattened across all 14 markets — FullModelPage groups by combo.market itself.
export function matchCAConditions(f, caPatterns) {
  if (!caPatterns) return { positive: [], avoid: [], emergingPositive: [], emergingAvoid: [], traps: [], contradictoryMarkets: [] };
  const dims = caExtractDims(f);
  const matchGroup = (byMarketObj) => {
    const out = [];
    for (const combos of Object.values(byMarketObj || {})) {
      for (const c of combos) if (c.conditions.every(cond => caConditionMatches(dims, cond))) out.push(c);
    }
    return out;
  };
  const positive = matchGroup(caPatterns.byMarket);
  const avoid = matchGroup(caPatterns.byMarketAvoid);
  // Emerging = low-test-n matches — kept fully separate from positive/avoid,
  // never merged in, so a small-sample fluke can't be mistaken for a
  // validated one just because it happened to also match.
  const emergingPositive = matchGroup(caPatterns.byMarketEmerging);
  const emergingAvoid = matchGroup(caPatterns.byMarketAvoidEmerging);
  // Same-market contradiction (dev journal, 2026-07-13): a market can carry
  // one combo that's a VALID positive and a DIFFERENT combo that's a VALID
  // avoid, both matching this fixture at once — never the same rule (traps
  // come from OVERFIT/DEGRADED status; these are two separately-mined VALID
  // combos that just happen to both fire here). Journal verdict: don't try
  // to explain both sides on screen — flag the market as a conflicting signal and
  // let display code suppress the individual cards for it.
  const positiveMarkets = new Set(positive.map(c => c.market));
  const avoidMarkets = new Set(avoid.map(c => c.market));
  const contradictoryMarkets = [...positiveMarkets].filter(m => avoidMarkets.has(m));
  // Traps (item #5) — combos that looked convincing on train but didn't hold
  // up on holdout (or the mirror: looked bad on train, held up fine).
  // ROOT CAUSE FIX (dev journal): only surfaced when the market has NO
  // validated positive or avoid match at all (this also naturally excludes
  // contradictory markets, since those are in both sets) — a market that
  // already has a clean lean, or is already flagged conflicting-signal, doesn't
  // need a trap caution stacked on top; the trap note only adds value when
  // it's the only thing this market has.
  const traps = matchGroup(caPatterns.byMarketTraps)
    .filter(c => !positiveMarkets.has(c.market) && !avoidMarkets.has(c.market));
  positive.sort((a, b) => (b.holdoutHitRate ?? -1) - (a.holdoutHitRate ?? -1));
  avoid.sort((a, b) => (a.holdoutHitRate ?? 101) - (b.holdoutHitRate ?? 101));
  emergingPositive.sort((a, b) => (b.holdoutHitRate ?? -1) - (a.holdoutHitRate ?? -1));
  emergingAvoid.sort((a, b) => (a.holdoutHitRate ?? 101) - (b.holdoutHitRate ?? 101));
  traps.sort((a, b) => Math.abs(b.gap ?? 0) - Math.abs(a.gap ?? 0));
  return { positive, avoid, emergingPositive, emergingAvoid, traps, contradictoryMarkets };
}

// ── CROSS-MARKET REASONING ENGINE (Phase 1, 2026-07-13) ─────────────────────
// Item #2 from the original CA session. Two rule shapes, both gated to VALID
// combos only (matchCAConditions's `positive`/`avoid` arrays are already
// VALID-only — see server's groupByMarket status filter — so no extra
// filtering needed here; an emerging or trap match can never feed a verdict).
//
// CA_SIDE_COMPONENTS is scaffolding, not output: it encodes which per-side
// markets a total-goals market logically decomposes into (Over 1.5 needs
// *a* goal from somewhere; Home O0.5 + Home O1.5 both flagged avoid on the
// home side means that goal is almost certainly not coming from home). This
// table is never surfaced as "Over 2.5 implies Over 1.5" — it only powers
// the origin-caveat check below, which fires on a specific avoid pattern,
// not on the implication itself.
// requiresBoth (2026-07-14, Annan/Dundee case): Over 1.5/2.5 can be hit
// entirely by ONE side scoring — home flagged avoid doesn't stop away alone
// covering it. BTTS structurally CANNOT hit without both sides scoring — a
// home-flagged-avoid BTTS pick isn't "resting on one path" the same soft way,
// it's riding entirely on the flagged side coming through. Same underlying
// avoid pattern, different real fragility, so it needs different treatment
// below rather than identical origin-caveat text for both.
const CA_SIDE_COMPONENTS = {
  "TB:Over 1.5": { home: ["TB:Home Over 0.5", "TB:Home Over 1.5"], away: ["TB:Away Over 0.5", "TB:Away Over 1.5"] },
  "TB:Over 2.5": { home: ["TB:Home Over 0.5", "TB:Home Over 1.5"], away: ["TB:Away Over 0.5", "TB:Away Over 1.5"] },
  "TB:BTTS":     { home: ["TB:Home Over 0.5"], away: ["TB:Away Over 0.5"], requiresBoth: true },
};
// Markets that can't both be true for the same fixture. Only pairs where a
// VALID positive match on both sides is a genuine logical conflict — DC1X
// and DCX2 both matching is NOT included here, since that's just a coherent
// "leans toward a draw" read, not a contradiction.
const CA_CONTRADICTION_PAIRS = [
  ["TB:1X2-Home", "TB:1X2-Away"],
  ["TB:1X2-Home", "TB:1X2-Draw"],
  ["TB:1X2-Away", "TB:1X2-Draw"],
  ["TB:1X2-Home", "TB:DCX2"],
  ["TB:1X2-Away", "TB:DC1X"],
];
const CA_MARKET_SHORT = m => (m || "").replace(/^TB:/, "");

// Pattern strength spectrum (dev journal, 2026-07-13: "not every positive or
// negative pattern should carry the same weight... the system needs a way to
// distinguish strong positives, weak positives, strong negatives, weak
// negatives"). Bucketed off |holdoutLift| — journal's own examples anchor the
// boundaries: +25pp and +21.8pp were called out as clearly strong, +14.1pp
// and +12.7pp as real-but-more-modest edges. A weak pattern isn't wrong, just
// lower-conviction — this is purely descriptive (badge/label), it doesn't
// gate anything by itself; CA_MIN_HOLDOUT_HR below is the separate, explicit
// gate for "bettable at all."
export function caPatternStrength(lift) {
  const abs = Math.abs(lift ?? 0);
  if (abs >= 20) return "strong";
  if (abs >= 10) return "moderate";
  return "weak";
}

// ── CA "STRONG PATTERN" CLASSIFICATION (Custom List View mode, 2026-07-18) ──
// Deliberately NOT caPatternStrength() above — that's a single-metric,
// lift-only descriptive label a per-combo card shows (a combo with a big
// lift reads "strong" there regardless of its actual hit rate). This is a
// genuinely different, composite gate for the Custom List "Strong Patterns"
// filter mode: absolute hit rate (train AND holdout) AND lift vs that
// market's own baseline (train AND holdout) all have to clear their own bar
// independently — a combo can't pass on lift alone.
// Positive and avoid are true mirrors, not "not positive": avoid asks for a
// LOW hit rate (train and holdout) plus a negative lift of the same
// magnitude — the opposite shape, not just the absence of the positive one.
// Avoid's hit-rate ceilings mirror the positive floors around 100 (100 -
// value) — same mirrored-around-100 shape the Emerging min-hit-rate filter
// already uses, so the two "Pattern Quality" modes read the same way.
//
// CONFIGURABLE (2026-07-18, Alden's request): trainHR/holdoutHR/lift/
// minSample used to be hardcoded. They're now a `thresholds` param with the
// original hardcoded numbers as defaults — the Custom List panel exposes
// editable inputs for these (defaulting to the numbers below), same pattern
// as the app's other Advanced Filter numeric inputs. minSample defaults to
// 0 (off) — Alden's 2026-07-18 call was that sample size shouldn't gate
// Strong by default, but he can still opt into a floor (>=10, >=15, etc.)
// via the same input rather than it being unavailable entirely.
export const CA_STRONG_MIN_TRAIN_HR         = 75;  // positive: train hit-rate floor
export const CA_STRONG_MIN_HOLDOUT_HR       = 70;  // positive: holdout hit-rate floor
export const CA_STRONG_MAX_TRAIN_HR_AVOID   = 20;  // avoid: train hit-rate ceiling
export const CA_STRONG_MAX_HOLDOUT_HR_AVOID = 20;  // avoid: holdout hit-rate ceiling
export const CA_STRONG_MIN_LIFT             = 20;  // pp, train AND holdout, vs that market's own baseline
export const CA_STRONG_MIN_SAMPLE           = 0;   // train AND holdout leg count floor — 0 = off (default)
// Single source of truth for the panel's default input values — keeps the
// UI defaults and the classifier's own fallback defaults from drifting
// apart if either is edited later.
export const CA_STRONG_DEFAULTS = {
  trainHR: CA_STRONG_MIN_TRAIN_HR,
  holdoutHR: CA_STRONG_MIN_HOLDOUT_HR,
  lift: CA_STRONG_MIN_LIFT,
  minSample: CA_STRONG_MIN_SAMPLE,
};
// Avoid's OWN defaults for when Avoid is filtered on its own (direction =
// "avoid") — these are the direct ceilings/floor, not derived by mirroring
// the positive numbers around 100. Matches the original hardcoded avoid
// ceiling this feature shipped with before thresholds became editable.
// Used directly (Alden's 2026-07-18 follow-up: 8 fields for pos+avoid was
// "confusing" — one 4-field panel is reused for whichever direction is
// active; "both" mode is the one case that still needs the 100-x mirror,
// since there's no separate avoid input to read in that mode).
export const CA_STRONG_AVOID_DEFAULTS = {
  trainHR: CA_STRONG_MAX_TRAIN_HR_AVOID,
  holdoutHR: CA_STRONG_MAX_HOLDOUT_HR_AVOID,
  lift: CA_STRONG_MIN_LIFT,
  minSample: CA_STRONG_MIN_SAMPLE,
};
export function isStrongCA(c, isAvoid, thresholds) {
  if (!c) return false;
  const t = thresholds || CA_STRONG_DEFAULTS;
  const trainHRBar   = t.trainHR   ?? CA_STRONG_MIN_TRAIN_HR;
  const holdoutHRBar = t.holdoutHR ?? CA_STRONG_MIN_HOLDOUT_HR;
  const liftBar      = t.lift      ?? CA_STRONG_MIN_LIFT;
  const sampleBar    = t.minSample ?? CA_STRONG_MIN_SAMPLE;
  // Missing-data defaults land on the FAILING side of the check (100 for
  // avoid's hit-rate floors, 0 for positive's) rather than null passing
  // through comparisons silently — an incomplete combo should never read as
  // "strong" by accident.
  const trainHR   = c.trainHitRate   ?? (isAvoid ? 100 : 0);
  const holdHR    = c.holdoutHitRate ?? (isAvoid ? 100 : 0);
  const trainLift = c.trainLift   ?? 0;
  const holdLift  = c.holdoutLift ?? 0;
  if (sampleBar > 0) {
    const trainN = c.trainSample ?? 0, holdN = c.holdoutSample ?? 0;
    if (trainN < sampleBar || holdN < sampleBar) return false;
  }
  if (!isAvoid) {
    return trainHR >= trainHRBar
        && holdHR  >= holdoutHRBar
        && trainLift >= liftBar
        && holdLift  >= liftBar;
  }
  // Avoid: DIRECT ceilings/floor if the caller supplied them (t.avoidTrainHR
  // etc — the "direction = avoid" case, its own field set, its own
  // defaults). Otherwise mirror the positive fields around 100 — the
  // "direction = both" case, where there's only one field set on screen and
  // it doubles as the positive threshold.
  const trainCeil = t.avoidTrainHR   ?? (100 - trainHRBar);
  const holdCeil  = t.avoidHoldoutHR ?? (100 - holdoutHRBar);
  const avoidLiftBar = t.avoidLift ?? liftBar;
  return trainHR <= trainCeil
      && holdHR  <= holdCeil
      && trainLift <= -avoidLiftBar
      && holdLift  <= -avoidLiftBar;
}

// SA-STRONG (2026-07-19, Davies request #5): SA's own "Strong" quality tier,
// mirroring isStrongCA's shape/defaults/avoid-mirroring exactly, but reading
// SA's actual pattern field names (trainHR/testHR/trainN/testN/lift — SA has
// ONE lift field, not separate train/holdout lifts like CA, so both the
// train and test hit-rate floors gate against that single lift value).
// SA's typical lift magnitudes run smaller than CA's in the sample pattern
// Davies shared (lift: 1.5 alongside trainHR 87.6 / baseHR 86.1), so the
// default lift floor here is set lower than CA's — fully editable either way.
export const SA_STRONG_MIN_TRAIN_HR       = 75;  // positive: train hit-rate floor
export const SA_STRONG_MIN_TEST_HR        = 70;  // positive: test/holdout hit-rate floor
export const SA_STRONG_MAX_TRAIN_HR_AVOID = 20;  // avoid: train hit-rate ceiling
export const SA_STRONG_MAX_TEST_HR_AVOID  = 20;  // avoid: test hit-rate ceiling
export const SA_STRONG_MIN_LIFT           = 10;  // pp vs baseHR — NOTE: lower default than CA's 20; SA's lift scale runs smaller, tune to taste
export const SA_STRONG_MIN_SAMPLE         = 0;   // train AND test leg count floor — 0 = off (default)
export const SA_STRONG_DEFAULTS = {
  trainHR: SA_STRONG_MIN_TRAIN_HR,
  testHR: SA_STRONG_MIN_TEST_HR,
  lift: SA_STRONG_MIN_LIFT,
  minSample: SA_STRONG_MIN_SAMPLE,
};
// Avoid's OWN defaults for when Avoid is filtered on its own (direction =
// "avoid") — same "8 fields is confusing, one 4-field panel reused per
// direction" pattern CA settled on (Alden's 2026-07-18 call).
export const SA_STRONG_AVOID_DEFAULTS = {
  trainHR: SA_STRONG_MAX_TRAIN_HR_AVOID,
  testHR: SA_STRONG_MAX_TEST_HR_AVOID,
  lift: SA_STRONG_MIN_LIFT,
  minSample: SA_STRONG_MIN_SAMPLE,
};
export function isStrongSA(p, isAvoid, thresholds) {
  if (!p) return false;
  const t = thresholds || SA_STRONG_DEFAULTS;
  const trainHRBar = t.trainHR   ?? SA_STRONG_MIN_TRAIN_HR;
  const testHRBar  = t.testHR    ?? SA_STRONG_MIN_TEST_HR;
  const liftBar    = t.lift      ?? SA_STRONG_MIN_LIFT;
  const sampleBar  = t.minSample ?? SA_STRONG_MIN_SAMPLE;
  // Missing-data defaults land on the FAILING side, same guard as isStrongCA —
  // an incomplete pattern object should never silently read as "strong".
  const trainHR = p.trainHR ?? (isAvoid ? 100 : 0);
  const testHR  = p.testHR  ?? (isAvoid ? 100 : 0);
  const lift    = p.lift    ?? 0;
  if (sampleBar > 0) {
    const trainN = p.trainN ?? 0, testN = p.testN ?? 0;
    if (trainN < sampleBar || testN < sampleBar) return false;
  }
  if (!isAvoid) {
    return trainHR >= trainHRBar && testHR >= testHRBar && lift >= liftBar;
  }
  // Avoid: direct ceilings if the caller supplied them (direction="avoid",
  // its own field set/defaults), otherwise mirror the positive fields
  // around 100 (direction="both", one field set doubling as both).
  const trainCeil = t.avoidTrainHR ?? (100 - trainHRBar);
  const testCeil  = t.avoidTestHR  ?? (100 - testHRBar);
  const avoidLiftBar = t.avoidLift ?? liftBar;
  return trainHR <= trainCeil && testHR <= testCeil && Math.abs(lift) >= avoidLiftBar;
}


// Shared floor/ceiling for "this is a genuinely bettable signal, not just an
// impressive lift number" (Sterling's call, 2026-07-13 — 60/40 as a
// reasonable symmetric starting point, revisit if it excludes too much or too
// little in practice). Used both by CA:Mix's best-market picker (CustomListView's
// caRows) and by computeCAVerdicts' strongest-lean rule below, so the two
// never disagree about what counts as strong enough to recommend.
export const CA_MIN_HOLDOUT_HR = 60;
export const CA_MAX_AVOID_HR = 40;
// Second, separate floor gate (2026-07-13 plan): a combo can clear the
// absolute-probability floor above and still be structurally trivial (e.g.
// 96% holdout HR off a 95% baseline — bettable, but adds nothing). Mirrors
// POOL_MIN_EMPIRICAL_RATE's role in the main engine's pool: a hard minimum
// before something's even eligible to be ranked, separate from the ranking
// formula itself.
export const CA_MIN_ELIGIBLE_LIFT = 5; // pp
// AVOID-ONLY stricter floor (2026-07-16, fresh-window replay finding): a
// strength-bucket breakdown of the July 11-16 out-of-sample replay showed
// avoid-direction lift magnitude actually DOES track real accuracy (weak
// <10pp lift -> 58.2% actual hit rate, barely better than a coin flip;
// strong >=20pp -> 40.2%, genuinely good). The SAME breakdown on the
// positive side showed no such pattern (moderate lift was the WORST
// bucket, not the middle of a trend) — so only avoid gets a stricter
// floor here; positive keeps CA_MIN_ELIGIBLE_LIFT=5 since there's no
// evidence a higher bar would help there.
export const CA_MIN_ELIGIBLE_LIFT_AVOID = 15; // pp, avoid-direction only
// How close a different-family candidate's score must be to the top pick's
// to also get a second verdict line (1 mandatory + 1 optional, per plan) —
// otherwise every fixture would pad out to two leans whether or not the
// second one actually adds anything.
export const CA_SECOND_LEAN_CLOSENESS = 0.85;

// ── Market families (2026-07-13 plan) ───────────────────────────────────────
// Deliberately NOT the same shape as READ_RANK_WEIGHT_* in config.js — those
// are static per-market handicaps Read needs because it ranks raw
// probability with no baseline concept (a 92% Over 1.5 needs an artificial
// penalty bolted on). CA already scores by lift (holdout − baseline), so an
// obvious market like Home Over 0.5 naturally scores near zero without any
// hardcoded weight — the problem Read solves by hand, CA solves structurally.
// What families ARE for: several markets can be different expressions of the
// same match story (three goal-markets agreeing isn't three independent
// proofs, it's one goal-story with three windows into it) — corroboration
// should count once, not three times. A market belongs to exactly one
// family, in both directions — a positive Home Over 0.5 + a positive Away
// Over 0.5 corroborate a goals story, and equally an avoid Home Over 0.5 +
// an avoid Away Over 0.5 corroborate a "steer away from goals" story.
export const CA_FAMILY_GOALS = new Set(["TB:Over 1.5", "TB:Over 2.5", "TB:BTTS", "TB:Home Over 0.5", "TB:Away Over 0.5"]);
export const CA_FAMILY_UNDER = new Set(["TB:Under 3.5", "TB:Under 4.5"]);
export const CA_FAMILY_RESULT = new Set(["TB:1X2-Home", "TB:1X2-Draw", "TB:1X2-Away", "TB:DC1X", "TB:DCX2"]);
export const CA_FAMILY_DOMINANCE = new Set(["TB:Home Over 1.5", "TB:Away Over 1.5"]);
// KNOWN SIMPLIFICATION: DC1X/1X2-Home (and DCX2/1X2-Away) overlap heavily —
// DC1X is literally Home-or-Draw, so a positive DC1X alongside a positive
// 1X2-Home isn't fully independent evidence the way two different goal
// markets are. Treating the whole result family as equal-weight corroborators
// for now; a finer per-pair overlap discount (like GPT's 0.5/0.2 idea) is a
// real refinement but needs real co-occurrence data to set honestly rather
// than another guessed number — revisit once the fixture-log (below) has
// enough rows to check.
function caFamilyOf(market) {
  if (CA_FAMILY_GOALS.has(market)) return "goals";
  if (CA_FAMILY_UNDER.has(market)) return "under";
  if (CA_FAMILY_RESULT.has(market)) return "result";
  if (CA_FAMILY_DOMINANCE.has(market)) return "dominance";
  return null;
}

// ── Recalibration layer (2026-07-16, root-cause fix) ────────────────────────
// WHY THIS EXISTS: replaying computeCAVerdicts against the July 11-16
// out-of-sample window (486 fresh fixtures, genuinely unseen by CA's own
// April-July10 mining/holdout split) showed claimed holdoutHitRate is
// systematically wrong in BOTH directions — positive combos overclaim by
// ~10-17pp across every bucket (claimed 90-99% -> actual 82.4%, n=347;
// claimed 60-69% -> actual 52.5%, n=629), negative/avoid combos underclaim
// by a similar margin the other way (claimed avoid-rate 0-9% -> actual
// 19.5%, n=200; claimed 40-49% -> actual 55.4%, n=505). Both regress toward
// baseline on truly fresh data — the fingerprint of the mining/threshold
// process having been iteratively hand-tuned against the same April-July10
// holdout window rather than a clean one-time split (Sterling's own
// suspicion, confirmed by this data).
// This ALSO turned out to be the real explanation for something that first
// looked like a sample-size problem: result/dominance-family markets
// (1X2-Home, 1X2-Away, DCX2, Away Over 1.5) collapsed hard at high n
// (e.g. 1X2-Home positive: 82.4% at n=17 vs 47.1% at n=240) while
// goals-family markets didn't. Making CA_SHRINK_K family-specific to fix
// that doesn't actually work — n/(n+k) is monotonic in n regardless of k,
// so raising k to punish large-n result-family combos would ALSO punish the
// small-n ones that are genuinely good. The real driver wasn't sample size,
// it was that claimed rates were wrong upstream — correcting that here
// means an inflated large-n combo gets pulled back down BEFORE shrinkage
// ever sees it, rather than trying to hack the shrink curve into doing a
// calibration curve's job.
// Fitted as a simple linear regression through the 8 claimed-rate bucket
// midpoints from that replay (see verdict-report-aggregate.mjs output,
// 2026-07-16). POOLED across all 14 markets, not yet per-family/per-market —
// coarse but directionally solid off 486 fixtures/6 days. Needs refreshing
// (and ideally splitting per family) as buildCAVerdictLogRows accumulates
// more genuinely-fresh outcomes over time — treat these two constants as a
// v1, not a permanent fixture.
const CA_RECAL_POS_SLOPE = 1.057, CA_RECAL_POS_INTERCEPT = -17.8;
const CA_RECAL_AVOID_SLOPE = 0.867, CA_RECAL_AVOID_INTERCEPT = 16.1;
function caRecalibratedHR(rawHR, isAvoid) {
  if (rawHR == null) return null;
  const v = isAvoid ? (CA_RECAL_AVOID_SLOPE * rawHR + CA_RECAL_AVOID_INTERCEPT)
                     : (CA_RECAL_POS_SLOPE * rawHR + CA_RECAL_POS_INTERCEPT);
  return Math.max(0, Math.min(100, v));
}

// Sample-size shrinkage (2026-07-13 plan) — replaces the old composite
// score's guessed ±5pp caps with an actual statistical technique (empirical
// Bayes-style shrinkage): score = lift × n/(n+k). A combo with n=12 gets
// discounted hard toward zero; n=400 is barely touched. Kills the "tiny-n
// combo with a freak +20pp lift" problem without a hard sample-size cutoff.
// NOTE (2026-07-16): kept as ONE global k, deliberately not made family-
// specific — see the recalibration comment above for why that doesn't
// actually fix the result-family collapse and the recalibration layer does.
export const CA_SHRINK_K = 25;
function caShrinkScore(lift, n) {
  const nn = n ?? 0;
  return Math.abs(lift ?? 0) * (nn / (nn + CA_SHRINK_K));
}

// Family corroboration bonus (2026-07-13 plan). Counts OTHER markets in the
// same family that ALSO have a clean (non-conflicting), floor-gated signal in
// the SAME direction as `market` — i.e. real, independently-mined support for
// the same underlying story, not just noise. Capped at 3 corroborators so the
// bonus stays bounded even for a 5-member family.
export const CA_FAMILY_CORROB_BONUS = 0.15; // multiplicative, per corroborator
export const CA_FAMILY_CORROB_CAP = 3;
function caFamilyCorroborationCount(market, isAvoid, cleanPositive, cleanAvoid) {
  const fam = caFamilyOf(market);
  if (!fam) return 0;
  const pool = isAvoid ? cleanAvoid : cleanPositive;
  // 2026-07-16: floor check now runs on the RECALIBRATED rate, not the raw
  // claimed one — see the recalibration layer above for why.
  const floorOk = c => {
    const recal = caRecalibratedHR(c.holdoutHitRate, isAvoid);
    return isAvoid ? recal <= CA_MAX_AVOID_HR : recal >= CA_MIN_HOLDOUT_HR;
  };
  const members = new Set();
  for (const c of pool) {
    if (c.market === market) continue;
    if (caFamilyOf(c.market) !== fam) continue;
    // 2026-07-16: mirrors the avoid-only stricter floor used in the main
    // eligibility filter below — a combo that wouldn't itself qualify as a
    // candidate shouldn't count as a corroborator either.
    const liftFloor = isAvoid ? CA_MIN_ELIGIBLE_LIFT_AVOID : CA_MIN_ELIGIBLE_LIFT;
    if (Math.abs(c.holdoutLift ?? 0) < liftFloor) continue;
    if (!floorOk(c)) continue;
    members.add(c.market);
  }
  return Math.min(members.size, CA_FAMILY_CORROB_CAP);
}

// Model agreement (2026-07-14 — reintroduces model probability, which
// caSafestScore had NO access to at all after the 2026-07-13 rewrite dropped
// it). The verdict-analyst logistic-regression pass (2026-07-14) found
// modelProb's learned weight (+0.222) landed in the same tier as CA's own
// bestPosLift/bestNegLift (+0.232/+0.196) — a real, independent signal, not
// noise, sitting well above familyCorrob's near-zero weight in that same run.
// Treated like family corroboration: a capped multiplicative nudge, kept as
// its own visible term rather than folded into the shrink score.
// Centered at 50 — reward when the model's own read AGREES with CA's lean
// (high modelProb backing a positive, low modelProb backing an avoid),
// PENALIZE when it disagrees. That penalty is deliberate, not just "no
// bonus" — disagreement is itself informative. This is exactly the gap the
// Annan/Dundee case exposed: CA's BTTS lean rested on a home-scoring leg the
// main model itself didn't rate highly (21% home win, well below what a
// blank-slate reading of Annan's own xG implied), while Over 2.5 didn't need
// that leg at all and the model agreed with it strongly (79% via its own Read
// output). Model agreement now pulls the safest score toward Over 2.5 and
// away from BTTS in a case shaped like that one, instead of treating both as
// equally solid.
// 2026-07-19 FIX (Alden's report): "TT 0.5" (Home/Away Over 0.5) was
// systematically winning the Mix tie-break over BTTS/Over 2.5 even when
// both were also Strong — the exact "obvious market scores near zero"
// problem this file's own comment above says lift-based shrink already
// solves structurally. It WAS solved there. The leak was here: this
// function measured model agreement against a flat 50, not against the
// market's own baseline. A market like Home Over 0.5 has a naturally high
// baseline (most teams score at least once most games) — its model
// probability sits far from 50 EVEN WHEN NOTHING UNUSUAL IS HAPPENING, so
// it collected a near-max "agreement" bonus for being an easy market, not
// for genuinely elevated support. Centering on c.holdoutBaselineHR instead
// (same baseline lift already uses) closes that gap: a market only earns
// agreement credit for sitting ABOVE its own normal level, exactly the
// same standard lift already holds every market to.
export const CA_MODEL_AGREEMENT_BONUS = 0.20;
function caModelProbFor(f, market) {
  const def = SA_MARKETS[market];
  if (!def || def._isPEMix) return null;
  const m = f.markets || {};
  const p = def.computeProb ? def.computeProb(m) : +(m[def.probKey] ?? 0);
  return Number.isFinite(p) && p > 0 ? p : null;
}
function caModelAgreementFactor(c, isAvoid, f) {
  const mp = caModelProbFor(f, c.market);
  if (mp == null) return 0; // no model prob available — neutral, no bonus or penalty
  const baseline = c.holdoutBaselineHR ?? 50; // fall back to the old flat-50 center only if a combo somehow has no baseline
  const agreement = isAvoid ? (baseline - mp) : (mp - baseline);
  // Normalize by the room actually available above/below that baseline, not
  // a flat 50 — a market that already sits at 85% baseline only has 15pp of
  // room to climb toward 100, so modelProb sitting at that ceiling should
  // read as "fully agreed, for this market," not as artificially weaker
  // than a 50%-baseline market's modelProb sitting at 100. Floor of 10 to
  // avoid a near-zero room blowing the ratio up for baselines pinned near
  // the extremes.
  const room = isAvoid ? Math.max(baseline, 10) : Math.max(100 - baseline, 10);
  return Math.max(-1, Math.min(1, agreement / room));
}

// Gap-stability — CA_GAP_SHRINK_K (2026-07-19, ported from Alden's
// verdict-ca-select.mjs) still the reused constant, but per
// CA_Ranking_Merge_Spec.md (2026-08-04) it no longer multiplies in as a
// separate discount factor (caStabilityFactor removed) — instead it shrinks
// the effective sample size Wilson sees below, so gap and n combine into one
// honest "how much do we trust this rate" number instead of two independent
// discounts stacked on top of each other.
export const CA_GAP_SHRINK_K = 5;
function effectiveN(n, gap, gapShrinkK) {
  return (n ?? 0) / (1 + Math.abs(gap ?? 0) / gapShrinkK);
}
// Standard Wilson score-interval lower bound, in 0-100 scale. Used on
// recalibrated HR with gap-adjusted n (not raw HR/raw n) — see
// CA_Ranking_Merge_Spec.md for why plain Wilson-on-raw-data was rejected
// (raw HR is systematically biased ~10-17pp high; gap is a stronger
// overfitting signal than n alone).
function wilsonLowerBound(p, n, z = 1.96) {
  if (!n || n <= 0) return 0;
  const denom = 1 + (z * z) / n;
  const center = p + (z * z) / (2 * n);
  const margin = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));
  return Math.max(0, (center - margin) / denom) * 100;
}

// Absolute hit-rate scaling (2026-07-19, same port). caShrinkScore only
// scores by LIFT magnitude — two combos with the same +15pp lift but
// holdoutHitRate 55% vs 85% used to score identically. This multiplies in
// (HR/100)^p — avoid direction uses ((100-HR)/100)^p — reusing config.js's
// own POOL_SCORE_P_EXP shape (already live-calibrated for "blend a rate with
// something else" in the main engine, same as CA_VALUE_P_EXP above).
// 2026-07-19 adaptation: scored against the RECALIBRATED holdout HR, not the
// raw claimed one — the recalibration layer (below) didn't exist yet when
// this formula was tested, but its whole point ("don't trust the raw
// claimed rate") applies here exactly as much as it already does to
// shrink's lift input just below.
// (caHitRateFactor removed 2026-08-04 — CA_Ranking_Merge_Spec.md's formula
// doesn't call it; HR scaling now happens via Wilson lower bound on
// gap-adjusted n instead. CA_HITRATE_SCALE_P_EXP stays exported since
// SC's server-side mirror still uses the same exponent shape independently.)
export const CA_HITRATE_SCALE_P_EXP = 2.0; // == POOL_SCORE_P_EXP

// "Safest lean" ranking — CA_Ranking_Merge_Spec.md (2026-08-04): three
// separate, labeled outputs instead of one opaque multiplied number, so two
// combos landing near the same rank can be told apart (one on stability, one
// on raw hit rate). Recalibration and family/model corroboration are kept
// exactly as before — real backtest signal, per the spec's explicit
// "do not touch" instruction — only the collapsing-into-one-number part
// changes.
//   predictiveStrength — recalHR itself, "how good does it look" (not
//     flipped for avoid — a LOW number IS what looks good there, same as
//     displaying any other rate)
//   reliability — Wilson lower bound of the FAVORABLE-direction probability
//     (recalHR flipped to 100-recalHR for avoid, so "lower bound" always
//     means "worst case still confidently in the direction this combo
//     argues for," for both positive and avoid — same flip-for-avoid
//     convention caHitRateFactor already uses just above)
//   verifiedEdge — reliability minus the same-direction baseline; the field
//     to actually rank/threshold on, since it already folds in both
//     recalibration and gap-adjusted sample size
function caSafestScore(c, isAvoid, cleanPositive, cleanAvoid, f) {
  const recalHR = caRecalibratedHR(c.holdoutHitRate, isAvoid) ?? c.holdoutHitRate;
  const nEff = effectiveN(c.holdoutSample, c.gap, CA_GAP_SHRINK_K);
  const favP = isAvoid ? (100 - recalHR) / 100 : recalHR / 100;
  const favBaseline = isAvoid ? (100 - (c.holdoutBaselineHR ?? 50)) : (c.holdoutBaselineHR ?? 50);
  const reliability = wilsonLowerBound(favP, nEff);
  const familyCorrobCount = caFamilyCorroborationCount(c.market, isAvoid, cleanPositive, cleanAvoid);
  const modelAgreementFactor = f ? caModelAgreementFactor(c, isAvoid, f) : 0;
  return {
    predictiveStrength: recalHR,
    reliability,
    verifiedEdge: reliability - favBaseline,
    familyCorrobCount,
    modelAgreementFactor,
  };
}


// Odds for a CA market — reuses SA_MARKETS' oddsKey (same lookup
// computeSAFeatures already does for SA) rather than a second way of reading
// fixture odds.
function caOddsFor(f, market) {
  const def = SA_MARKETS[market];
  if (!def || def._isPEMix || !def.oddsKey) return null;
  const o = f.odds?.[def.oddsKey];
  return o > 1 ? o : null;
}

// "Best value" score (2026-07-13 plan) — ONLY for positive-direction combos
// with real odds available. Reuses config.js's own POOL_SCORE_P_EXP formula
// (score = empiricalRate^p × ln(o)/o) rather than inventing a third value
// formula — that one is already live-calibrated in the main engine for
// exactly this "blend probability with payout" problem. Requires a real edge
// first (CA's own holdout HR must beat the market's implied probability) —
// no edge, no value candidacy, regardless of how the formula would score it.
// NOTE: p=2.0 is carried over as a starting assumption, not a proven
// transfer — CA's holdoutHitRate is an empirical win-rate off a mined
// pattern, not a fully-calibrated probability the way the main engine's
// empiricalRate is (that one's already been through the deflation curves).
// Worth validating against CA's own outcomes once there's enough logged data.
export const CA_VALUE_P_EXP = 2.0; // == POOL_SCORE_P_EXP
// Own quality floor for best-value (2026-07-17, sweep finding): the edge-
// over-odds check in caValueScore alone isn't a strong enough filter —
// fully decoupled from the lean floor, best-value came back at 50.7% win
// rate (n=227), a coinflip. Swept a recalibrated-HR floor from 0 to 85
// against the fresh replay: 60->66.0%(n=100), 65->67.8%(n=90),
// 70->72.7%(n=77), 75->75.0%(n=48), 80->77.8%(n=27, getting noisy),
// 85->87.5%(n=8, one game either way swings this ~12pp — not a stable
// estimate). 70 is where the gain over 60 is still clearly real (confidence
// bands don't overlap) while keeping meaningful coverage (~1 in 6 fresh
// fixtures) — 75 is a defensible alternative if coverage matters less than
// squeezing out a few more accuracy points. Not swept per-family yet
// (same caveat as the recalibration curve itself — coarse v1, refine as
// more fresh-log data accumulates).
export const CA_MIN_VALUE_HR = 70;
function caValueScore(c, f) {
  const odds = caOddsFor(f, c.market);
  if (!odds) return null;
  const impliedP = (1 / odds) * 100;
  // 2026-07-16: recalibrated, not raw — an inflated claimed HR could
  // otherwise look like it beats the market's implied probability when the
  // real (recalibrated) rate wouldn't, which is exactly the false-edge
  // scenario this floor exists to prevent.
  const hr = caRecalibratedHR(c.holdoutHitRate, false) ?? 0;
  if (hr <= impliedP) return null; // no edge, not a value candidate at all
  if (hr < CA_MIN_VALUE_HR) return null; // 2026-07-17: own quality floor, see constant's comment
  return Math.pow(hr / 100, CA_VALUE_P_EXP) * (Math.log(odds) / odds);
}

// Rule 1's origin-caveat classification, extracted (2026-07-17) so callers
// that only need "which markets are origin-excluded" — buildCAVerdictLogRows
// pulls it from computeCAVerdicts' own verdicts since it already calls that
// anyway; the Mix block below does NOT already call computeCAVerdicts, so it
// uses this directly — don't run the full computeCAVerdicts (Rule 3 scoring,
// best-value, etc.) just to get this, especially in a per-fixture render
// loop. Single source of truth either way; computeCAVerdicts's Rule 1 below
// just adds the display text on top of this.
function caOriginClassifications(positive, avoid) {
  const avoidMarkets = new Set(avoid.map(c => c.market));
  const bestPerMarket = new Map();
  for (const p of positive) if (!bestPerMarket.has(p.market)) bestPerMarket.set(p.market, p);
  const out = [];
  for (const p of bestPerMarket.values()) {
    const components = CA_SIDE_COMPONENTS[p.market];
    if (!components) continue;
    const homeFlagged = components.home.every(m => avoidMarkets.has(m));
    const awayFlagged = components.away.every(m => avoidMarkets.has(m));
    if (homeFlagged && awayFlagged) {
      out.push({ market: p.market, holdoutHitRate: p.holdoutHitRate, type: "unclear-origin", flaggedSide: null, otherSide: null });
    } else if (homeFlagged || awayFlagged) {
      const flaggedSide = homeFlagged ? "home" : "away";
      const otherSide = homeFlagged ? "away" : "home";
      out.push({
        market: p.market, holdoutHitRate: p.holdoutHitRate,
        type: components.requiresBoth ? "fragile-origin" : "origin-caveat",
        flaggedSide, otherSide,
      });
    }
  }
  return out;
}

// caMatches: the return value of matchCAConditions above. Returns an array of
// verdict objects, computed over the FULL positive/avoid lists (not whatever
// the UI currently has capped/filtered for display) — the fixture-level
// picture, independent of which market pill is selected.
export function computeCAVerdicts(caMatches, f) {
  const { positive = [], avoid = [], contradictoryMarkets = [] } = caMatches || {};
  const verdicts = [];
  // Rule 0 — same-market conflicting signal (dev journal, 2026-07-13). Checked
  // before the `!positive.length` early-return below, since a market can be
  // flagged conflicting-signal even on a fixture with zero clean positive
  // matches left (all its positives got absorbed into a contradiction).
  for (const m of contradictoryMarkets) {
    verdicts.push({
      type: "conflicting-signal", market: m,
      text: `${CA_MARKET_SHORT(m)} has both a validated positive and a validated avoid pattern matching this fixture — treated as a conflicting signal, not a lean either way.`,
    });
  }
  if (!positive.length) return verdicts;

  // Rule 1 — origin caveat, ONE verdict per MARKET, not per matched combo.
  // ROOT CAUSE FIX (2026-07-13): a single fixture routinely matches many
  // overlapping VALID combos in the same market — e.g. totalXG>=3.0 and
  // totalXG>=3.5 can both be true for one fixture at once, and the mining
  // pass produces both as separate combos. The origin-caveat check below
  // only ever depends on p.market + avoidMarkets, never on which specific
  // combo p is, so looping over every matched positive combo emitted the
  // identical sentence once per combo — confirmed live: "Over 1.5 matched,
  // but away scoring is flagged avoid..." repeated 13x verbatim before this
  // fix, one per matching Over-1.5 combo. Deduping to one representative
  // combo per market removes the duplication without changing the rule's
  // logic. `positive` is already sorted best-holdout-first (see
  // matchCAConditions above), so the first combo seen per market is the
  // strongest one — kept as the representative for holdoutHitRate display.
  for (const oc of caOriginClassifications(positive, avoid)) {
    if (oc.type === "unclear-origin") {
      verdicts.push({
        type: "unclear-origin", market: oc.market, holdoutHitRate: oc.holdoutHitRate,
        text: `${CA_MARKET_SHORT(oc.market)} matched, but both home and away scoring are flagged avoid on this fixture — the pattern held up on holdout, but neither side looks like the source. Worth a second look before trusting it.`,
      });
    } else if (oc.type === "fragile-origin") {
      // Fragile origin (2026-07-14, Annan/Dundee case): this market can't
      // hit AT ALL without the flagged side scoring — not a caveat on an
      // otherwise-fine pick, the pick's entire outcome rides on the side
      // CA itself flagged avoid. Distinct type so Rule 3 can exclude it
      // from lean/value candidacy the same way unclear-origin already is.
      verdicts.push({
        type: "fragile-origin", market: oc.market, holdoutHitRate: oc.holdoutHitRate,
        text: `${CA_MARKET_SHORT(oc.market)} matched, but it needs BOTH sides to score and ${oc.flaggedSide} scoring is flagged avoid — this pick rides entirely on the flagged side coming through, not a soft caveat.`,
      });
    } else {
      verdicts.push({
        type: "origin-caveat", market: oc.market, holdoutHitRate: oc.holdoutHitRate,
        text: `${CA_MARKET_SHORT(oc.market)} matched, but ${oc.flaggedSide} scoring is flagged avoid on both thresholds — likely ${oc.otherSide}-side driven, not spread across both teams. Real signal, resting on one path.`,
      });
    }
  }

  // Rule 2 — contradiction flag.
  const positiveMarkets = new Set(positive.map(c => c.market));
  for (const [a, b] of CA_CONTRADICTION_PAIRS) {
    if (positiveMarkets.has(a) && positiveMarkets.has(b)) {
      verdicts.push({
        type: "contradiction", market: a, market2: b,
        text: `${CA_MARKET_SHORT(a)} and ${CA_MARKET_SHORT(b)} both matched as valid patterns, but they can't both be right — one of them is misfiring on this fixture. Treat both with extra caution.`,
      });
    }
  }

  // Rule 3 — Safest lean + optional second + Best value (2026-07-13 full
  // rewrite, replaces the old Holdout-HR-dominant composite score entirely).
  // caSafestScore (shrunk |lift| × family corroboration × model agreement) can now win in
  // EITHER direction — a well-corroborated avoid signal can be the fixture's
  // actual safest lean, not just a caveat sentence buried under a positive
  // pick. Same exclusions as before: conflicting-signal markets (Rule 0) and
  // unclear-origin markets (Rule 1's stronger flag) never candidate. Two
  // floor gates apply: CA_MIN_HOLDOUT_HR/CA_MAX_AVOID_HR (genuinely
  // bettable/avoidable in absolute terms) AND CA_MIN_ELIGIBLE_LIFT (not
  // structurally trivial even if the absolute number looks fine — mirrors
  // POOL_MIN_EMPIRICAL_RATE's role in the main engine's pool).
  const unclearOriginMarkets = new Set(
    verdicts.filter(v => v.type === "unclear-origin" || v.type === "fragile-origin").map(v => v.market)
  );
  const contradictorySet = new Set(contradictoryMarkets);
  // 2026-07-16: lift floor and HR floor both now check the RECALIBRATED
  // rate — a claimed 96% that's really ~82% shouldn't sail through
  // CA_MIN_HOLDOUT_HR just because the raw number looked fine. Avoid
  // direction also gets the stricter CA_MIN_ELIGIBLE_LIFT_AVOID floor (see
  // that constant's comment — weak avoid lift doesn't discriminate real
  // outcomes the way weak positive lift's absence of a pattern suggested).
  const eligible = (c, isAvoid) => {
    if (contradictorySet.has(c.market) || unclearOriginMarkets.has(c.market)) return false;
    const liftFloor = isAvoid ? CA_MIN_ELIGIBLE_LIFT_AVOID : CA_MIN_ELIGIBLE_LIFT;
    return Math.abs(c.holdoutLift ?? 0) >= liftFloor;
  };
  const cleanPositive = positive.filter(c => eligible(c, false) && caRecalibratedHR(c.holdoutHitRate, false) >= CA_MIN_HOLDOUT_HR);
  const cleanAvoid = avoid.filter(c => eligible(c, true) && caRecalibratedHR(c.holdoutHitRate, true) <= CA_MAX_AVOID_HR);

  // 2026-07-31 REPLACED (caStoryVerdict.js): the old top-pick here was
  // `scored` (cleanPositive+cleanAvoid combined, ranked by caSafestScore,
  // single winner in EITHER direction). Root cause of the "steer away only"
  // complaint: when the winner happened to be an avoid signal and nothing
  // positive independently cleared CA_MIN_HOLDOUT_HR, the fixture's
  // headline verdict was "steer away from X" with nothing stakeable —
  // insight, not a verdict. caStoryVerdict.js's resolveStoryVerdict fixes
  // this by grouping evidence into match theses (home/away dominance, open
  // game, slow game) and walking them best-first through MAIN then
  // SUBSIDIARY markets until one clears the SAME bettable floor this file
  // already uses (CA_MIN_HOLDOUT_HR/CA_MIN_ELIGIBLE_LIFT — it mirrors both
  // constants rather than importing them, see that file's DUPLICATION NOTE
  // for why). Only when every coherent thesis fails to produce a bettable
  // market does it fall back to an avoid-direction headline — same
  // "insight, not verdict" outcome as before, just no longer the FIRST
  // thing tried. `cleanPositive`/`cleanAvoid` above stay in place — the
  // second-lean pick below still uses caSafestScore off those pools
  // unchanged, that's a different, unrelated feature (secondary lean from
  // a different market family) than the "which is the top pick" bug fixed
  // here.
  // 2026-07-31: dominanceGate reuses xgHomeDominant/xgAwayDominant (already
  // defined for the SA filter list — home/away xG at least 2x the other side
  // AND a >=1.0 gap) plus f.competitionRisk (server.js's existing cup/
  // friendly/international classifier, newly exposed on the fixture object)
  // — a market clearing its statistical gate on a cup-tie mismatch or a
  // weakened-squad friendly isn't the same signal as clearing it in a normal
  // league fixture with a real quality gap behind it.
  const caStoryCtx = {
    getModelProb: market => caModelProbFor(f, market),
    dominanceGate: { home: xgHomeDominant(f) && !f.competitionRisk, away: xgAwayDominant(f) && !f.competitionRisk },
  };
  const storyVerdict = resolveStoryVerdict(caMatches, caStoryCtx);
  let topMarket = null;
  if (storyVerdict.status === "MAIN" || storyVerdict.status === "SUBSIDIARY") {
    topMarket = storyVerdict.market;
    const topTripletMS = caSafestScore(storyVerdict.combo, false, cleanPositive, cleanAvoid, f);
    verdicts.push({
      type: "strongest-lean", market: storyVerdict.market, holdoutHitRate: storyVerdict.combo.holdoutHitRate,
      direction: "positive", thesis: storyVerdict.thesis, confidence: storyVerdict.confidence,
      predictiveStrength: topTripletMS.predictiveStrength, reliability: topTripletMS.reliability, verifiedEdge: topTripletMS.verifiedEdge,
      text: storyVerdict.status === "MAIN"
        ? `${CA_MARKET_SHORT(storyVerdict.market)} looks like the strongest clean lean here — holdout ${storyVerdict.combo.holdoutHitRate}% (+${storyVerdict.combo.holdoutLift}pp vs baseline).`
        : `${CA_MARKET_SHORT(storyVerdict.market)} — fallback expression of the ${storyVerdict.thesis} story (main market not trusted enough), holdout ${storyVerdict.combo.holdoutHitRate}% (+${storyVerdict.combo.holdoutLift}pp).`,
    });
    if (storyVerdict.avoidNote) {
      const avoidCombo = cleanAvoid.find(c => c.market === storyVerdict.avoidNote.market);
      const avoidTriplet = avoidCombo ? caSafestScore(avoidCombo, true, cleanPositive, cleanAvoid, f) : null;
      verdicts.push({
        type: "second-lean", market: storyVerdict.avoidNote.market, holdoutHitRate: storyVerdict.avoidNote.holdoutHitRate,
        direction: "avoid",
        ...(avoidTriplet ? { predictiveStrength: avoidTriplet.predictiveStrength, reliability: avoidTriplet.reliability, verifiedEdge: avoidTriplet.verifiedEdge } : {}),
        text: `Also worth noting: steer away from ${CA_MARKET_SHORT(storyVerdict.avoidNote.market)} — holdout ${storyVerdict.avoidNote.holdoutHitRate}% (${storyVerdict.avoidNote.holdoutLift}pp), a different market family.`,
      });
    }
  } else if (storyVerdict.avoidNote) {
    // Genuine no-verdict: no coherent thesis produced a bettable market.
    // The avoid note surfaces honestly as the headline (CAVerdictBlock
    // already renders avoid-direction with no CTA — "insight, not a
    // verdict" is a UI-level fact here, not something this function needs
    // to encode further).
    topMarket = storyVerdict.avoidNote.market;
    const headlineAvoidCombo = cleanAvoid.find(c => c.market === storyVerdict.avoidNote.market);
    const headlineAvoidTriplet = headlineAvoidCombo ? caSafestScore(headlineAvoidCombo, true, cleanPositive, cleanAvoid, f) : null;
    verdicts.push({
      type: "strongest-lean", market: storyVerdict.avoidNote.market, holdoutHitRate: storyVerdict.avoidNote.holdoutHitRate,
      direction: "avoid",
      ...(headlineAvoidTriplet ? { predictiveStrength: headlineAvoidTriplet.predictiveStrength, reliability: headlineAvoidTriplet.reliability, verifiedEdge: headlineAvoidTriplet.verifiedEdge } : {}),
      text: `Steer away from ${CA_MARKET_SHORT(storyVerdict.avoidNote.market)} — holdout only ${storyVerdict.avoidNote.holdoutHitRate}% (${storyVerdict.avoidNote.holdoutLift}pp vs baseline). No positive story clears the floor on this fixture.`,
    });
  }

  // Second lean (unchanged feature, re-scoped to exclude whatever market
  // just became the headline above so the same market can't appear twice).
  // Closeness gate preserved: only worth a second line if it scores within
  // CA_SECOND_LEAN_CLOSENESS of the headline's own caSafestScore. The
  // headline no longer comes from a caSafestScore ranking (it comes from
  // resolveStoryVerdict), so its score is looked up here instead of reused
  // from a prior sort — same floors (cleanPositive/cleanAvoid), so the
  // headline's combo is found there whenever it cleared this function's
  // own unclear-origin exclusion (the one case computeCAVerdicts checks
  // that caStoryVerdict's own marketPasses doesn't). If it isn't found
  // there, skip the closeness gate rather than guess — no second lean.
  if (topMarket) {
    const headlineInPositive = cleanPositive.find(c => c.market === topMarket);
    const headlineInAvoid = !headlineInPositive ? cleanAvoid.find(c => c.market === topMarket) : null;
    const headlineCombo = headlineInPositive || headlineInAvoid;
    const topTriplet = headlineCombo
      ? caSafestScore(headlineCombo, !!headlineInAvoid, cleanPositive, cleanAvoid, f)
      : null;
    const scored = [
      ...cleanPositive.filter(c => c.market !== topMarket).map(c => ({ c, isAvoid: false, triplet: caSafestScore(c, false, cleanPositive, cleanAvoid, f) })),
      ...cleanAvoid.filter(c => c.market !== topMarket).map(c => ({ c, isAvoid: true, triplet: caSafestScore(c, true, cleanPositive, cleanAvoid, f) })),
    ];
    if (scored.length && topTriplet != null && !verdicts.some(v => v.type === "second-lean")) {
      // Rank by verifiedEdge (spec Step 5) — already folds in recalibration
      // and gap-adjusted sample size. familyCorrobCount/modelAgreementFactor
      // only break ties within ~1pp, not used as primary sort keys.
      scored.sort((a, b) => {
        const d = b.triplet.verifiedEdge - a.triplet.verifiedEdge;
        if (Math.abs(d) > 1) return d;
        const tieA = a.triplet.familyCorrobCount + a.triplet.modelAgreementFactor;
        const tieB = b.triplet.familyCorrobCount + b.triplet.modelAgreementFactor;
        return tieB - tieA;
      });
      const topFamily = caFamilyOf(topMarket);
      const second = scored.find(e => caFamilyOf(e.c.market) !== topFamily && e.triplet.verifiedEdge >= topTriplet.verifiedEdge * CA_SECOND_LEAN_CLOSENESS);
      if (second) {
        verdicts.push({
          type: "second-lean", market: second.c.market, holdoutHitRate: second.c.holdoutHitRate,
          direction: second.isAvoid ? "avoid" : "positive",
          predictiveStrength: second.triplet.predictiveStrength, reliability: second.triplet.reliability, verifiedEdge: second.triplet.verifiedEdge,
          text: second.isAvoid
            ? `Also worth noting: steer away from ${CA_MARKET_SHORT(second.c.market)} — holdout ${second.c.holdoutHitRate}% (${second.c.holdoutLift}pp), a different market family.`
            : `Also worth noting: ${CA_MARKET_SHORT(second.c.market)} as a secondary lean — holdout ${second.c.holdoutHitRate}% (+${second.c.holdoutLift}pp), a different market family.`,
        });
      }
    }
  }

  // Best value — positive direction only (you stake something; "avoid" isn't
  // itself a stakeable market). Requires real odds AND a real edge (CA's own
  // recalibrated holdout HR beats the market's implied probability, AND
  // clears CA_MIN_VALUE_HR) via caValueScore — never shown just because the
  // formula would score it, only when there's an actual price to compare
  // against.
  // DECOUPLED from cleanPositive/CA_MIN_HOLDOUT_HR (2026-07-17): it used to
  // draw only from cleanPositive, meaning a combo had to clear the LEAN
  // floor to even be considered for value — but a value pick's job is
  // "beats the price," not "is a confident enough lean," and those aren't
  // the same question. Coupling them cut best-value's count 405->100 for
  // almost no accuracy gain when this was first tested. Still excludes
  // same-market contradictions and unclear/fragile-origin (those aren't
  // floor-related — they mean the signal's own direction is ambiguous,
  // which is a real reason to exclude regardless of value vs lean).
  if (f) {
    const valueEligible = positive.filter(c => !contradictorySet.has(c.market) && !unclearOriginMarkets.has(c.market));
    const valueCandidates = valueEligible.map(c => ({ c, score: caValueScore(c, f) })).filter(x => x.score != null);
    if (valueCandidates.length) {
      valueCandidates.sort((a, b) => b.score - a.score);
      const bestValue = valueCandidates[0].c;
      const odds = caOddsFor(f, bestValue.market);
      verdicts.push({
        type: "best-value", market: bestValue.market, holdoutHitRate: bestValue.holdoutHitRate,
        text: `Best value: ${CA_MARKET_SHORT(bestValue.market)} at ${odds} — holdout ${bestValue.holdoutHitRate}% beats the market's own ${(+(100 / odds).toFixed(1))}% implied price.`,
      });
    }
  }

  return verdicts;
}

// ── SC (Settlement Conditions) — third pattern engine (2026-08-03) ─────────
// Matching + verdict logic moved server-side (Davies's call) — see
// server.js's POST /api/sc-match: it ports settlement-conditions-miner.mjs's
// actual extractDims() verbatim (not a re-derived client guess) and applies
// a reliability-FLAG model per market (favorable/unfavorable/conflicted),
// not a CA-style competing-picks verdict — SC diagnoses whether conditions
// favor trusting a market's existing SA/CA signal, it isn't picking bets of
// its own. The frontend just POSTs the fixtures it already has in memory and
// gets back { [fixtureId]: { flags: { [marketKey]: { status, holdoutHitRate,
// holdoutLift, reason } } } } — no mined-pattern JSON on the client at all.
export const SC_MARKET_LABELS = Object.entries({
  homeWin: "1X2-Home", awayWin: "1X2-Away", draw: "1X2-Draw", dc1X: "DC1X", dcX2: "DCX2",
  over15: "Over 1.5", over25: "Over 2.5", under35: "Under 3.5", under45: "Under 4.5",
  bttsYes: "BTTS", homeOver05: "Home Over 0.5", homeOver15: "Home Over 1.5",
  awayOver05: "Away Over 0.5", awayOver15: "Away Over 1.5",
}).map(([id, label]) => ({ id, label }));
// Same family ids SA_TO_FAMILY_ID's values already use (over15/under35/
// bttsyes/dc1x/dc2x/homewin/draw/awaywin/homeo05/homeo15/awayo05/awayo15) —
// SC's pool keys just differ in case/spelling, not in what they mean, so
// this is a direct translation, not a new set of ids.
export const SC_MARKET_TO_FAMILY_ID = {
  homeWin: "homewin", awayWin: "awaywin", draw: "draw", dc1X: "dc1x", dcX2: "dc2x",
  over15: "over15", over25: "over25", under35: "under35", under45: "under45",
  bttsYes: "bttsyes", homeOver05: "homeo05", homeOver15: "homeo15",
  awayOver05: "awayo05", awayOver15: "awayo15",
};
// Client-side mirror of server.js's SC_MARKET_ODDS_FIELDS — that table only
// ever existed server-side (SC matching moved there 2026-08-03), but ticket
// generation (2026-08-04) needs to price SC legs off f.odds directly, same
// as it already does for SA/CA via SA_MARKETS' oddsKey. Same confirmed
// subset as the server-side version — markets without a confirmed odds key
// just don't produce a priceable leg from SC, same graceful-skip as
// everywhere else this gap shows up.
export const SC_MARKET_ODDS_FIELD = {
  homeWin: "o1", awayWin: "o2", under35: "under35odds", under45: "under45odds",
  bttsYes: "bttsYesOdds", homeOver05: "over05odds", awayOver05: "over05odds",
};

// ── Cross-engine market-id translation (2026-08-06 fix) ────────────────────
// SA and CA share one flat market-id namespace ("TB:Over 2.5" etc — see
// SA_TO_FAMILY_ID's keys). SC does NOT — its own ids are bare family strings
// ("over25", "homeWin", ... — see SC_MARKET_LABELS above), a different
// scheme entirely. Combine mode's "lock every checked engine onto one
// market" logic used to copy a market id straight from whichever engine was
// just picked onto the others with zero translation — harmless SA<->CA
// (same namespace already), but SC<->SA/CA silently handed CA (or SA) an id
// it has no entry for (e.g. "over25" has no CA_MARKET_LABELS match), which
// broke that engine's row matching for the rest of the combine — this is
// the crash from selecting an SC market while CA is checked into Combine.
// familyOfMarket/marketForEngine round-trip every mirror through the shared
// family id (SA_TO_FAMILY_ID's values / SC_MARKET_TO_FAMILY_ID's values —
// already the same vocabulary) instead of a raw string copy.
const FAMILY_TO_TB_MARKET = Object.fromEntries(
  Object.entries(SA_TO_FAMILY_ID).map(([tb, fam]) => [fam, tb])
);
const FAMILY_TO_SC_MARKET = Object.fromEntries(
  Object.entries(SC_MARKET_TO_FAMILY_ID).map(([sc, fam]) => [fam, sc])
);
function familyOfMarket(engine, marketId) {
  if (marketId == null) return null;
  if (engine === "sc") return SC_MARKET_TO_FAMILY_ID[marketId] ?? null;
  // sa and ca share one namespace; CA:Mix/CA:Verdict/PE:Mix have no
  // single-family equivalent (they resolve per-fixture), so no translation —
  // familyOfMarket correctly returns null for those, same as an unknown id.
  return SA_TO_FAMILY_ID[marketId] ?? null;
}
function marketForEngine(engine, familyId) {
  if (familyId == null) return null;
  if (engine === "sc") return FAMILY_TO_SC_MARKET[familyId] ?? null;
  return FAMILY_TO_TB_MARKET[familyId] ?? null; // same TB: id serves both sa and ca
}

// ── CA Verdict headline resolver (2026-08-02) ───────────────────────────────
// Single source of truth for "which verdict is THE headline" — same
// promotion rule FullModelPage's CAVerdictBlock uses (an avoid-direction
// strongest-lean gets demoted in favor of a positive/best-value verdict when
// one exists, so the Custom List Verdict row and FMP's own Verdict panel can
// never disagree about which market is the fixture's actual headline).
// Returns null when there's no strongest-lean verdict at all (genuine
// no-verdict fixture, or zero clean positive matches — see computeCAVerdicts'
// early return).
export function resolveCAVerdictHeadline(verdicts) {
  if (!verdicts || !verdicts.length) return null;
  const top = verdicts.find(v => v.type === "strongest-lean");
  if (!top) return null;
  if (top.direction === "avoid") {
    const promoted = verdicts.find(v => v !== top && (v.direction === "positive" || v.type === "best-value"));
    if (promoted) return promoted;
  }
  return top;
}

// ── CA Verdict Log row builder (2026-07-14) ─────────────────────────────────
// Pure function, no network call — one row per (market, direction) the
// verdict engine considered for this fixture, collapsed to the single best
// combo per market/direction (arrays are already strongest-first out of
// matchCAConditions) rather than every threshold variant, per the plan's
// "collapse each market to one signal first" step. The caller (CustomListView's
// log button) batches these across every fixture for a date and POSTs once to
// /api/ca-verdict-log — see that endpoint's own comment for the full
// leakage-guard rationale behind caSnapshotDate.
export function buildCAVerdictLogRows(f, caPatterns) {
  if (!caPatterns || !f) return [];
  const caMatches = matchCAConditions(f, caPatterns);
  const verdicts = computeCAVerdicts(caMatches, f);
  const { positive, avoid, contradictoryMarkets = [] } = caMatches;
  const contradictorySet = new Set(contradictoryMarkets);

  const bestPerMarket = list => {
    const seen = new Map();
    for (const c of list) if (!seen.has(c.market)) seen.set(c.market, c);
    return [...seen.values()];
  };
  const bestPositive = bestPerMarket(positive);
  const bestAvoid = bestPerMarket(avoid);
  // 2026-07-17: same recalibration + avoid-only lift floor fix as
  // computeCAVerdicts' Rule 3 (see that function's `eligible`/cleanPositive/
  // cleanAvoid for the full rationale) — this function computes its own
  // independent copy of the same filter rather than calling into
  // computeCAVerdicts' internals, so it has to be kept in sync by hand.
  // Missed this the first time the recalibration patch went in; caught on
  // review — the log's clearsFloor/familyCorrobCount/safestScore columns
  // would otherwise have silently disagreed with what topLean/secondLean
  // above actually reflect.
  // 2026-07-17 (follow-up): also excludes unclear/fragile-origin markets now
  // — this function never did, only computeCAVerdicts' Rule 3 did, so a
  // market whose positive signal came entirely from one goal-less side
  // could still show clearsFloor=true here while never actually being
  // eligible for a lean. Pulled straight from `verdicts` (already computed
  // above) instead of re-deriving Rule 1 a third time.
  const unclearOriginMarkets = new Set(
    verdicts.filter(v => v.type === "unclear-origin" || v.type === "fragile-origin").map(v => v.market)
  );
  const eligibleLog = (c, isAvoid) => {
    if (contradictorySet.has(c.market) || unclearOriginMarkets.has(c.market)) return false;
    const liftFloor = isAvoid ? CA_MIN_ELIGIBLE_LIFT_AVOID : CA_MIN_ELIGIBLE_LIFT;
    return Math.abs(c.holdoutLift ?? 0) >= liftFloor;
  };
  const cleanPositive = positive.filter(c => eligibleLog(c, false) && caRecalibratedHR(c.holdoutHitRate, false) >= CA_MIN_HOLDOUT_HR);
  const cleanAvoid = avoid.filter(c => eligibleLog(c, true) && caRecalibratedHR(c.holdoutHitRate, true) <= CA_MAX_AVOID_HR);

  const fixtureId = f.id ?? f.fixtureId ?? f.matchId ?? `${f.teams?.home}__${f.teams?.away}__${f.time || ""}`;
  const topLean = verdicts.find(v => v.type === "strongest-lean");
  const secondLean = verdicts.find(v => v.type === "second-lean");
  const bestValueV = verdicts.find(v => v.type === "best-value");

  const rowFor = (c, isAvoid) => {
    const conflict = contradictorySet.has(c.market);
    const clearsFloor = eligibleLog(c, isAvoid) &&
      (isAvoid ? caRecalibratedHR(c.holdoutHitRate, true) <= CA_MAX_AVOID_HR : caRecalibratedHR(c.holdoutHitRate, false) >= CA_MIN_HOLDOUT_HR);
    const odds = !isAvoid ? caOddsFor(f, c.market) : null;
    const triplet = clearsFloor ? caSafestScore(c, isAvoid, cleanPositive, cleanAvoid, f) : null;
    return {
      fixtureId, date: f.date || null, league: f.league || null,
      home: f.teams?.home || null, away: f.teams?.away || null,
      market: c.market, direction: isAvoid ? "avoid" : "positive", family: caFamilyOf(c.market),
      holdoutHitRate: c.holdoutHitRate ?? null, holdoutLift: c.holdoutLift ?? null,
      holdoutBaselineHR: c.holdoutBaselineHR ?? null, holdoutSample: c.holdoutSample ?? null,
      trainHitRate: c.trainHitRate ?? null, gap: c.gap ?? null,
      conflictFlag: conflict, clearsFloor,
      familyCorrobCount: triplet ? triplet.familyCorrobCount : 0,
      shrinkScore: caShrinkScore(c.holdoutLift, c.holdoutSample),
      modelProb: caModelProbFor(f, c.market),
      modelAgreement: triplet ? triplet.modelAgreementFactor : null,
      // 2026-08-04: safestScore (single collapsed number) replaced with the
      // three separate CA_Ranking_Merge_Spec.md fields — same underlying
      // computation, just no longer hidden inside one multiplied product.
      predictiveStrength: triplet ? triplet.predictiveStrength : null,
      reliability:        triplet ? triplet.reliability : null,
      verifiedEdge:       triplet ? triplet.verifiedEdge : null,
      odds, valueEdgePP: odds ? +((caRecalibratedHR(c.holdoutHitRate, false) ?? 0) - (100 / odds)).toFixed(1) : null, // 2026-07-17: recalibrated, was raw
      valueScore: !isAvoid ? caValueScore(c, f) : null,
      isTopLean: !!topLean && topLean.market === c.market,
      isSecondLean: !!secondLean && secondLean.market === c.market,
      isBestValue: !!bestValueV && bestValueV.market === c.market,
      caSnapshotDate: caPatterns.generatedAt || null,
      loggedAt: new Date().toISOString(),
      outcome: null, // filled in later by a separate join-with-results pass
    };
  };

  return [...bestPositive.map(c => rowFor(c, false)), ...bestAvoid.map(c => rowFor(c, true))];
}

// ── EXCLUDE SELECTION GROUPS ─────────────────────────────────────────────
// Same two-tier shape as Custom Pick (market family → individual line/option),
// but used for exclusion: each option gets its own toggle so a single line
// (e.g. "Draw" or "Home or Away") can be excluded without nuking the whole family.
const EXCLUDE_SELECTION_GROUPS = [
  { label:"1X2", options:[
      { id:"homewin", label:"Home Win" },
      { id:"draw",    label:"Draw" },
      { id:"awaywin", label:"Away Win" },
  ]},
  { label:"Double Chance", options:[
      { id:"dc_1x", label:"Home or Draw" },
      { id:"dc_x2", label:"Away or Draw" },
      { id:"dc_12", label:"Home or Away" },
  ]},
  { label:"BTTS", options:[
      { id:"bttsyes", label:"BTTS Yes" },
      { id:"bttsno",  label:"BTTS No" },
  ]},
  { label:"Goals O/U", options:[
      { id:"Over 1.5",  label:"Over 1.5" },
      { id:"Over 2.5",  label:"Over 2.5" },
      { id:"Over 3.5",  label:"Over 3.5" },
      { id:"Under 2.5", label:"Under 2.5" },
      { id:"Under 3.5", label:"Under 3.5" },
      { id:"Under 4.5", label:"Under 4.5" },
  ]},
  { label:"Team Total", options:[
      { id:"home_tt", label:"Home Team O/U" },
      { id:"away_tt", label:"Away Team O/U" },
  ]},
];

// Classifies a pick (label + market, optionally a fixture for team names) into one
// of the granular ids above. Falls back to the raw market string for goals O/U
// (those market values — "Over 2.5", "Under 3.5", etc — are already line-specific).
function getExcludeSelectionId(pick, f) {
  const label  = (pick?.label ?? pick?.pick ?? "").trim();
  const market = pick?.market || "";
  const pLow   = label.toLowerCase();
  const home = f?.teams?.home, away = f?.teams?.away;

  if (market === "1X2" || pLow === "draw" || /\bwin\b/.test(pLow)) {
    if (pLow === "draw") return "draw";
    if (home && label === `${home} Win`) return "homewin";
    if (away && label === `${away} Win`) return "awaywin";
    if (pLow.endsWith(" win")) {
      const teamPart = label.slice(0, -4);
      if (home && home.startsWith(teamPart)) return "homewin";
      if (away && away.startsWith(teamPart)) return "awaywin";
    }
    return "homewin";
  }
  if (market === "DC" || /home or|away or|or away|or draw|^1x$|^x2$|^12$/.test(pLow)) {
    if (pLow.includes("home or draw") || pLow.startsWith("home win or draw") || pLow === "1x") return "dc_1x";
    if (pLow.includes("away or draw") || pLow.includes("draw or away") || pLow === "x2") return "dc_x2";
    return "dc_12";
  }
  if (market === "BTTS" || /btts|both teams/.test(pLow)) {
    return pLow.includes("no") ? "bttsno" : "bttsyes";
  }
  if (market === "TeamTotal" || /to score|o0\.5|o1\.5/i.test(label)) {
    if (home && label.startsWith(home)) return "home_tt";
    if (away && label.startsWith(away)) return "away_tt";
    return "home_tt";
  }
  // Goals O/U — market is already "Over X.5" / "Under X.5"
  if (market) return market;
  const m = label.match(/(Over|Under)\s*([\d.]+)/i);
  if (m) return `${m[1][0].toUpperCase()}${m[1].slice(1).toLowerCase()} ${m[2]}`;
  return label || market;
}

export const STRATEGY_LABELS = {
  home_win:"Home Win", away_win:"Away Win", btts_value:"BTTS Value",
  home_goalfest:"H Goalfest", away_goalfest:"A Goalfest",
  over25_quality:"O2.5 Quality", low_scoring:"Low Scoring",
  draw:"Draw",
};

function xgHomeDominant(f){ return f.markets.homeXG >= f.markets.awayXG*2 && (f.markets.homeXG - f.markets.awayXG) >= 1; }
function xgAwayDominant(f){ return f.markets.awayXG >= f.markets.homeXG*2 && (f.markets.awayXG - f.markets.homeXG) >= 1; }

const makeStatFilters = (xgT, thr, xgHomeT, xgAwayT) => {
  const hT = xgHomeT ?? xgT;
  const aT = xgAwayT ?? xgT;
  return [
  { id:"has_read",      label:"Has Read",         desc:"Has a non-fallback Read pick",      fn:f=>!!(f.theRead && !f.theRead.isFallback) },
  { id:"has_edge",      label:"Has Edge",          desc:"Edge signal found",                 fn:f=>!!f.theEdge },
  { id:"has_radar",     label:"Goal Radar",        desc:"At least one team in Goal Radar",   fn:f=>!!f.goalRadar },
  { id:"btts_q",        label:`BTTS ≥${thr.btts}%`,   desc:`BTTS Yes ≥${thr.btts}%`,      fn:f=>f.markets.bttsYes>=thr.btts },
  // xG filters — fine-grained control
  { id:"xg_home_min",   label:`Home xG ≥${hT}`,   desc:`Home team xG ≥${hT}`,              fn:f=>f.markets.homeXG>=hT },
  { id:"xg_away_min",   label:`Away xG ≥${aT}`,   desc:`Away team xG ≥${aT}`,              fn:f=>f.markets.awayXG>=aT },
  // xg_both renamed to Total xG — logic changed from "both teams individually ≥X"
  // to "combined total ≥X". The old fn was too restrictive (required EACH team ≥X)
  // which silently excluded games where one team drives total xG (e.g. 2.4 + 0.8).
  // xg_home_min and xg_away_min remain as individual per-team filters above.
  { id:"xg_both",       label:`Total xG ≥${xgT}`,  desc:`Home+Away combined xG ≥${xgT}`,   fn:f=>(f.markets.homeXG+f.markets.awayXG)>=xgT },
  { id:"xg_total_high", label:`Total xG ≥${(xgT*1.8).toFixed(1)}`, desc:`Home+Away xG ≥${(xgT*1.8).toFixed(1)}`, fn:f=>(f.markets.homeXG+f.markets.awayXG)>=(xgT*1.8) },
  { id:"xg_home",       label:"Home xG Dom",       desc:"Home xG 2× away + gap ≥1",         fn:f=>xgHomeDominant(f) },
  { id:"xg_away",       label:"Away xG Dom",       desc:"Away xG 2× home + gap ≥1",         fn:f=>xgAwayDominant(f) },
  { id:"cs_home",       label:`Home CS ≥${thr.csHome}%`, desc:`Home clean sheet ≥${thr.csHome}%`, fn:f=>f.markets.homeCS>=thr.csHome },
  { id:"cs_away",       label:`Away CS ≥${thr.csAway}%`, desc:`Away clean sheet ≥${thr.csAway}%`, fn:f=>f.markets.awayCS>=thr.csAway },
  { id:"def_weak_home", label:"H Def Weak",        desc:"Home CS < 20%",                    fn:f=>f.markets.homeCS<20 },
  { id:"def_weak_away", label:"A Def Weak",         desc:"Away CS < 20%",                    fn:f=>f.markets.awayCS<20 },
  { id:"homewin_str",   label:`H Win ≥${thr.hWin}%`,  desc:`Home win ≥${thr.hWin}%`,      fn:f=>f.markets.homeWin>=thr.hWin },
  { id:"awaywin_str",   label:`A Win ≥${thr.aWin}%`,  desc:`Away win ≥${thr.aWin}%`,      fn:f=>f.markets.awayWin>=thr.aWin },
  { id:"odds_floor",    label:`Odds ≥${thr.oddsFloor}`, desc:`Read/Edge odds ≥${thr.oddsFloor}`, fn:f=>{ const o=f.theRead?.anchor?.odds||f.theEdge?.odds; return o!=null ? o>=thr.oddsFloor : true; } },
  { id:"low_xg",        label:"Low xG",            desc:"Total xG < 2.0",                   fn:f=>(f.markets.homeXG+f.markets.awayXG)<2.0 },
  { id:"volatile",      label:"Volatile",          desc:"Volatile league",                  fn:f=>!!f.volatileLeague },
  { id:"live",      label:"LIVE",     desc:"Currently in progress",
    icon:<svg width="9" height="9" viewBox="0 0 8 8"><circle cx="4" cy="4" r="4" fill="currentColor" opacity=".25"/><circle cx="4" cy="4" r="2.5" fill="currentColor"/></svg>,
    fn:f=>{ const s=(f.state||"").toLowerCase(); return ["inprogress","live","1h","1sthalf","ht","halftime","2h","2ndhalf","et","extratime","penaltyshootout"].includes(s); } },
  { id:"scheduled", label:"Upcoming", desc:"Not yet started",
    icon:<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>,
    fn:f=>{ const s=(f.state||"").toLowerCase(); return s===""||s==="notstarted"||s==="scheduled"||s==="prematch"; } },
  { id:"draw_prob",     label:"Draw ≥30%",         desc:"Draw probability ≥30%",            fn:f=>f.markets.draw>=30 },
  { id:"draw_balanced", label:"Balanced",          desc:"|homeWin−awayWin| ≤15",            fn:f=>Math.abs((f.markets.homeWin||0)-(f.markets.awayWin||0))<=15 },
  { id:"draw_xg_range", label:"xG 1.4–2.6",       desc:"Total xG between 1.4 and 2.6",     fn:f=>{ const t=(f.markets.homeXG||0)+(f.markets.awayXG||0); return t>=1.4&&t<=2.6; } },
  ];
};

